  [1240319446357760] = "Consumir <Img tex2d=\"%s\" width=\"54\" height=\"54\"/> %s para desbloquear o slot?",
  [1240319446226688] = "Existe uma opção de pontuação mais alta entre os resultados de reforjamento atuais. Você quer continuar reforjando?",
