  [1240389777659648] = "A assembleia de guerra de clubes foi iniciada; confirme para se teletransportar para perto do invocador.",
  [1240389777659392] = "<Highlight_L> [ %s ] </> ganhou <Highlight_L> [ %s ] </> pontos protegendo a bandeira!",
