  [1240389777120256] = "%s usou a habilidade de comando <PVPHighlight> Proteção do Santuário </>.",
  [1240389777120000] = "Usamos a habilidade <PVPHighlight> Proteção do Santuário </> , <PVPHighlight> restaurando 50% da Saúde máxima de todos os nossos guardas </> .",
  [1240389777119744] = "%s usou a habilidade de comando <PVPHighlight> Rally Teleport </>.",
  [1240389777119488] = "Usamos a habilidade <PVPHighlight> Rally Teleport </> , <PVPHighlight> convocando todos os nossos membros para se teletransportarem para o ponto de encontro </> .",
  [1240389777119232] = "%s usou a habilidade de comando <PVPHighlight> Zeroing Edict </> .",
  [1240389777118976] = "Usamos a habilidade <PVPHighlight> Zeroing Edict </> , removendo o atual tempo de espera da ressurreição para todos os nossos membros <PVPHighlight> , incluindo companheiros de equipe que morreram nos últimos 5 segundos </> .",
  [1240389777118720] = "Infelizmente, o campo inimigo <PVPHighlight> ocupou com sucesso o altar </> .",
  [1240389777118464] = "Nossa facção <PVPHighlight> capturou com sucesso o altar </> , <PVPHighlight> convocando um super veículo em nossa base </> . Você pode ir e usá-lo.",
  [1002827350549248] = "Capaz de pegar emprestado o poder do seu eu passado e evocar imagens das lacunas da história. Para um estudioso de outrora, enquanto algo for possuído, não estará verdadeiramente perdido; a história é o seu tesouro sem fim.",
  [1240389777118208] = "%s usou a habilidade de comando <PVPHighlight> Teletransporte Rally </>.",
  [1002827618979072] = "Você se tornou a fronteira entre o mortal e o misterioso; seu pensamento, percepção e poder estão todos se afastando da categoria humana.",
  [1240389777117952] = "%s usou a habilidade de comando <PVPHighlight> Assistência ao equipamento de cerco </>.",
  [1240389777117696] = "%s usou a habilidade de comando <PVPHighlight> Bênção da Torre Alta </>.",
  [1240389777117440] = "%s usou a habilidade de comando <PVPHighlight> Declaração de Derrotar o Inimigo </>.",
  [1240389777117184] = "%s usou a habilidade de comando <PVPHighlight> Chifre destruidor de cidades </>.",
  [1240389777116928] = "Usamos a habilidade <PVPHighlight> Teleportation Rally </> . Nossa facção <PVPHighlight> pode se teletransportar rapidamente do nosso ponto de spawn para o ponto de teletransporte alvo </> .",
  [1240389777116672] = "Usamos a habilidade <PVPHighlight> Assistência ao equipamento de cerco </>. Uma Carruagem de Canhão é convocada em nossa base <PVPHighlight> , que pode causar grandes danos às torres defensivas inimigas </> .",
  [1240389777116416] = "Usamos a habilidade <PVPHighlight> Bênção da Torre Alta </>. As torres defensivas alvo de nossa facção <PVPHighlight> ganham um escudo defensivo de alto valor </> por 10 segundos.",
  [1240389777116160] = "Usamos a habilidade <PVPHighlight> Declaração de Derrotar o Inimigo </>. Todos os membros da nossa facção <PVPHighlight> ganham 15% de supressão em todos os caminhos </> por 20 segundos.",
