  [1240319446380032] = "Você quer se teletransportar para o ponto de check-in?",
  [1240319446379776] = "Este modelo foi carregado no Dress-up Plaza. Excluir este modelo também irá <Highlight> excluí-lo simultaneamente </> do Dress-up Plaza. Você deseja continuar?",
