  [1003374422001664] = "Vinho tinto",
  [1003374422009856] = "Pó de Agrimônia",
  [409232268657408] = "Cada contato aproxima o usuário do próprio conhecimento.",
  [409232268669696] = "O anel branco prateado envolve o corpo e a alma, solidificando todos os votos para a eternidade.",
