  [1240251532094721] = "Reduz a probabilidade de ser atingido pelo controle Lento, reduzindo a taxa básica de acerto em até metade, e nega o acerto Lento da fonte de controle.",
  [1240251532094465] = "Reduz a probabilidade de ser atingido pelo controle de Estagnação, reduzindo a taxa de acerto base em até metade, e nega o impacto de Estagnação da fonte de controle.",
  [774607015513088] = "Liga Quádrupla",
