  [1169951775867904] = "Leve Arnold de carruagem de volta para <h> Blackthorn </>",
  [1169951775867392] = "Desperte <h> Arnold </>",
  [1169951775866368] = "<h> Toque com cuidado em </>",
  [1169951775865600] = "<h> Tentativa de aproximação </>",
  [1231454365290752] = "Faça um roaming",
  [1169951775864576] = "Fale com <h> Sra. Brown </>",
  [1169951775864064] = "<h> Bata na porta </>",
  [1046805399736064] = "A Lua Carmesim surge, <Disable> Lobisomem fortalecido! </> Jogadores com muitas pilhas Tear irão <Disable> cair no caos e atacar seus companheiros de equipe </> .",
  [1046805399760640] = "Anthea transformará todos os jogadores em bonecos para um jogo de Luz Vermelha, Luz Verde. Os jogadores devem passar para o lado de Anthea para quebrar a transformação. Durante isso, Anthea dará as costas aos jogadores e fará uma contagem regressiva, convocando bonecos para atacar pelo campo. Após a contagem regressiva, ela se virará para encarar os jogadores, petrificando quem ainda estiver em movimento. Se ninguém alcançá-la após várias rodadas do jogo, ela causará danos massivos em todo o campo.",
  [1169951775863808] = "Vá para <h> casa de Arnold </>",
  [1169951775863552] = "Pegue uma carruagem para o <h> Distrito Norte </>",
  [1169951775863296] = "<h> Compre bolo </>",
  [1169951775863040] = "Fale com <h> Sra. Slin </>",
