  [519041160596992] = "Por favor, dê uma olhada ao redor.",
  [519041160609280] = "O cavalheirismo deve ser transmitido.",
  [519041160621568] = "Descanse aqui um pouco primeiro.",
  [519041160646144] = "Cerveja, cerveja... onde tem mais cerveja gelada?",
  [519041160687104] = "Fale baixo!",
