  [527767192061696] = "<Assistant_Title1> Bruxa e Fera </> \n <Assistant_Title2> Categoria de conquista: </> Enredo - Vida na Era\n <Assistant_Title2> Condição de desbloqueio: </> Complete a Vida na Era missão \"Bruxa e Fera\".",
