  [1165565540529152] = "Coletar item com TemplateID especificado: O jogador cria um objeto público com base na lista InstanceID (não tem efeito no mundo aberto), teletransporta-se para coordenadas de cena especificadas.",
  [475333694327552] = "Salvamos Tingen.",
  [1165624327804416] = "Fale com <h> Luo Yao </>.",
  [1165565540521728] = "Vá para o local de acionamento especificado: o jogador envia o item missão, o jogador cria um objeto público com base na lista InstanceID (não tem efeito no mundo aberto), o jogador chama a animação de passagem do tempo.",
  [1165565540520960] = "Use missão item próximo ao local especificado: Player envia missão item, Player reproduz texto visível apenas para si mesmo, execução atrasada, Player reproduz texto visível apenas para si mesmo.",
