  [360778595434240] = "Eu prometo.",
  [879817876572672] = "Tingen espelhada",
  [211107843584000] = "Crítico aumentado em *d.",
  [224645580144128] = "Se qualquer jogador realizar um desvio enquanto a habilidade estiver varrendo, todos os jogadores ganham imunidade a danos.",
