  [57657788475392] = "Beyonder Aprendiz",
  [1090789622953474] = "Antes de receber dano, ganhe um efeito de <HighLight> Escudo </> com duração de 8 segundos e um efeito de aceleração de 50% com duração de 4 segundos. Este efeito tem um recarga de 20 segundos.",
  [1090789622953473] = "Liberar o primeiro estágio de <HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\"> Flame Jump </> aumenta a velocidade de movimento em 50% por 4 segundos.",
  [634008576722946] = "Doce Vento do Oceano",
  [453413523756544] = "<DecH> Artesanato: </> Beyonder Escultura e Incrustação de Cristal\nUma pulseira ritual com um toque tão frio quanto gelo e neve, aparentemente capaz de ajudar um Beyonder a conter seu espiritualidade.",
  [1090789622951170] = "<HyperLink stylename=\"M_Link\" u=\"86021050\" color=\"#f4a067\"> Dissuasão </> aplica um efeito de estagnação de 4 segundos após atingir um inimigo.",
  [1090789622951169] = "O dano causado por <HyperLink stylename=\"M_Link\" u=\"86021070\" color=\"#f4a067\"> Dream Weaving </> a alvos no estado <HighLight> Plague </> é aumentado em 30%.",
  [1090789622945538] = "O recarga interno de <HyperLink stylename=\"M_Link\" u=\"86013010\" color=\"#f4a067\"> Soul of the Blazing Sun </> é reduzido em 30 segundos, e o efeito de lesão grave durante o estado é reduzido de 80% para 75%.",
  [752067564568320] = "Empregada Louca",
  [752067564606208] = "Velho Tomás",
  [360778595365376] = "Bonnie: Já chega, Lily.",
  [140809429070592] = "Acione Dragon Breath para cobrir uma ampla área de inimigos à frente.",
  [471142611556864] = "Cronologia Viajante",
  [1090789622942723] = "<HyperLink stylename=\"M_Link\" u=\"86011050\" color=\"#f4a067\"> Purificação da Luz Sagrada </> ganha a habilidade de ramificação <HighLight> Limpeza da Chama Sagrada </>: \nPurifica jogadores inimigos que se dissipam dentro do alcance, desencadeando uma explosão que causa dano aos alvos sobreviventes. A habilidade de ramificação tem um Recarga de 8 segundos.",
  [1090786670184704] = "O custo inicial de <HighLight> Secret Peeking </> e o subsequente custo incremental de <HighLight> Secret Peeking </> de <HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\"> Torrent of Information </> são ambos reduzidos em 3 pontos. O dano de <HyperLink stylename=\"M_Link\" u=\"86071060\" color=\"#f4a067\"> Olhos de Inquisição Misteriosa </> é aumentado em 30%.",
  [1090786670183936] = "Após liberar <HyperLink stylename=\"M_Link\" u=\"86071080\" color=\"#f4a067\"> Gambit of the Ages </> , ganhe o efeito <HighLight> Critical Limit </> por 10 segundos. \n <FaintYellow> Limite Crítico </>: Cada uso de uma habilidade ou ataque básico reduz o recarga das habilidades atualmente em recarga em 0,5 segundos, até uma redução máxima de 0,5 segundos por segundo.",
  [206984137895168] = "Chuva de Flechas",
  [598342094641152] = "Vá para Blackthorn",
  [1090786670181376] = "O custo inicial de <HighLight> Secret Peeking </> e o subsequente custo incremental de <HighLight> Secret Peeking </> de <HyperLink stylename=\"M_Link\" u=\"86073010\" color=\"#f4a067\"> Torrent of Information </> são ambos reduzidos em 3 pontos.",
  [1090786670179840] = "A probabilidade de acionamento de <HyperLink stylename=\"M_Link\" u=\"86075010\" color=\"#f4a067\"> Torrente de Informações </> é aumentada em 10%. Quando <HyperLink stylename=\"M_Link\" u=\"86075010\" color=\"#f4a067\"> Torrente de Informações </> for acionada, ganhe 5 pontos adicionais de <HighLight> Espiação Secreta </> . Depois de liberar o ataque básico aprimorado <HyperLink stylename=\"M_Link\" u=\"86070040\" color=\"#f4a067\"> Lança de Longinus </> , ganhe 2,5 segundos de <Orange> Super Armadura </> .",
  [1090786670177024] = "A duração do Knockup de <HyperLink stylename=\"M_Link\" u=\"86061100\" color=\"#f4a067\"> Twilight Combo Slash </> contra jogadores inimigos foi estendida para 3 segundos. Além disso, ao lançar <HyperLink stylename=\"M_Link\" u=\"86061100\" color=\"#f4a067\"> Twilight Combo Slash </> , se <HyperLink stylename=\"M_Link\" u=\"86061050\" color=\"#f4a067\"> Silver Rapier </> não estiver em Recarga , <HyperLink stylename=\"M_Link\" u=\"86061050\" color=\"#f4a067\"> Silver Rapier </> será lançado automaticamente; este efeito pode ser ativado mesmo se <HyperLink stylename=\"M_Link\" u=\"86061050\" color=\"#f4a067\"> Silver Rapier </> não estiver equipado.",
  [1090786670176512] = "Na postura ofensiva, <HyperLink stylename=\"M_Link\" u=\"86061080\" color=\"#f4a067\"> Angry Slam </> atingindo os inimigos com <HighLight> Decay </> causa dano adicional de perseguição em pequena área e estende a duração de <HighLight> Decay </> em 5 segundos. \n Na Postura Ofensiva, lançar <HyperLink stylename=\"M_Link\" u=\"86061023\" color=\"#f4a067\"> Royal Court Command </> após Hunter Instant Slash derrubar os inimigos na frente e entrar no estado <HighLight> Berserk </> por 6 segundos. <HighLight> Ataques de estado Berserk </> restauram a saúde ao atingir os inimigos, com um <Highlight> 1 </> segundo interno recarga .",
  [752067564593920] = "Projeção da Rainha de Paus",
  [1090786670173696] = "Depois de receber dano, se a Vida atual estiver abaixo de 50% e <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\"> Dawn Armor </> não estiver em Recarga , <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\"> Dawn Armor </> será lançado automaticamente; este efeito pode ser ativado mesmo se <HyperLink stylename=\"M_Link\" u=\"86061040\" color=\"#f4a067\"> Dawn Armor </> não estiver equipado. \n <HyperLink stylename=\"M_Link\" u=\"86061020\" color=\"#f4a067\"> Demon Hunter Instant Slash </> ganha um novo ramo, <HyperLink stylename=\"M_Link\" u=\"86061060\" color=\"#f4a067\"> Exorcism Slash </> : Quando em Forma de Defesa, lançá-lo em um inimigo tem o mesmo efeito que o Demon Hunter Instant Slash original; quando lançado em um aliado, remove os efeitos Soft Crowd Control e Slow do aliado e concede 20% de redução de dano e 25% de aumento de velocidade de movimento por 5 segundos.",
  [1090786670172160] = "Na Forma de Defesa, a Redução de Dano passiva do <HyperLink stylename=\"M_Link\" u=\"86065010\" color=\"#f4a067\"> Mestre de Armas </> foi aumentada para 30%. \n <HyperLink stylename=\"M_Link\" u=\"86061060\" color=\"#f4a067\"> Guardian Wall </> ganha o novo ramo <HyperLink stylename=\"M_Link\" u=\"86061063\" color=\"#f4a067\"> Guardian Rampart </> : Implanta um campo que concede um escudo de alto valor e 15% de redução de dano aos dois aliados com a saúde mais baixa em um raio de 30 metros. O valor do escudo aumenta com base no número de <HighLight> Marcas do Crepúsculo </> consumidas.",
  [936784443753216] = "<FontSmall> Dupla Utopia · Pesadelo </>",
