  [1068726108465920] = "%s ↓",
  [1068726108465664] = "%s ↑",
  [1068726108465152] = "Consumir <img id=\"2000529\" width=\"40\" height=\"40\"/> %d para abrir",
  [1068726108464896] = "Consumir <img id=\"2000529\" width=\"40\" height=\"40\"/> <Red> %d </> para abrir",
  [1068726108463872] = "Insira o conteúdo de recrutamento",
  [1068726108463616] = "Definir meta",
  [1143699056628992] = "Ele lentamente endireitou o corpo e estendeu a mão para empurrar o olho direito. Ali mesmo, um monóculo que parecia feito de cristal já havia surgido.",
  [1068726108462848] = "Não há dados disponíveis",
  [1068726108462592] = "Exibir título ao conversar",
  [1068726108462080] = "Modo Social",
  [1068726108461312] = "Selecione <Menu_Highlight> %d </> / %d pratos ou sopas",
  [1068726108460800] = "%s (Eu)",
  [1068726108460288] = "Habilidade de ressurreição restante recarga <YELLOW> %d </> segundos",
  [1068726108459776] = "Recarregue <HighLight> qualquer quantia </> para resgatar os seguintes presentes gratuitamente",
  [1068726108459520] = "Compre qualquer um dos seguintes <Highlight_Yellow> pacotes de presente </> para resgatar o presente de primeira compra",
  [1068726108456704] = "Acessório de cintura exclusivo",
  [1068726108456448] = "Principais %s projeções",
  [1068726108456192] = "Rodada %s partida encerrada",
  [1068726108455936] = "Rodada %s começando em breve",
  [1068726108455680] = "Próximo %s %02d: %02d",
  [1068726108455168] = "Cadastro em andamento",
  [1068726108454912] = "A %s briga de clube",
  [1068726108454400] = "Um único olhar para trás, como uma gota de perfume caindo em água parada, espalhando-se e estendendo-se. No balançar da saia, no hálito caótico e quente, todas as defesas desabaram na fragrância. Submeta-se, disposto a se tornar o troféu e a posse desse encanto irresistível.",
  [1068726108454144] = "A fragrância persistente surge como uma maré, e os sussurros turvos são quentes e abrasadores no coração. Mas não importa como a saia roce seu rosto ou a fragrância penetre em sua respiração, você nunca afunda. Quando o cheiro persistente se dissipa, a bruxa desnorteada sofre pessoalmente uma derrota dolorosa por uma vontade inflexível.",
  [1068726108453888] = "Derramando tudo em um sussurro encantador, tentando usar passos de dança para encurtar a distância do afundamento mútuo – mas o final é uma máscara quebrada, a fragrância se dissipou, e aquele que uma vez cativou todos os seres vivos é pessoalmente subjugado por um olhar imóvel. Talvez o encanto oculto do outro esteja muito além do seu.",
  [1068726108453632] = "A fragrância é como a ponta de um dedo invisível, roçando cada centímetro de vontade que tenta se manter firme. Esse olhar durou apenas um instante, mas quando a bainha da saia passou pela luz das velas, os passos de dança perderam o ritmo e, a partir de então, nunca mais conseguiram encontrar o próprio ritmo. Curve-se, torne-se um cativo da beleza; este é outro nome concedido aos caídos.",
  [1068726108453376] = "O duelo começa",
  [1068726108453120] = "%s / %s",
