  [1068726108421120] = "Aceitar Comissão",
  [1090786670163968] = "O terceiro estágio da <HyperLink stylename=\"M_Link\" u=\"86031010\" color=\"#f4a067\"> Card Flying Dagger </> aplica 6 segundos de <HighLight> Bleed </> , fazendo com que o alvo perca 2% da saúde máxima do lançador por segundo (não excedendo 60% do ataque do lançador). \n <HyperLink stylename=\"M_Link\" u=\"86031070\" color=\"#f4a067\"> Flame Jump </> lançamento de segundo estágio remove efeitos de <HighLight> Crowd Control </> de você mesmo.",
