  [1068726108306176] = "No co-desempenho em equipe, a equipe participará da performance em conjunto",
  [316868191881473] = "Sucesso!",
  [409232268654592] = "Deixemos que todas as coisas revelem seus símbolos originais sob o olhar da razão.",
