  [1059930014491392] = "Montar",
  [1059930014490368] = "Controle de multidão rígido (por exemplo, atordoamento)",
  [580887615937536] = "Obtenha a classificação [Railway Tycoon] %d /5 vezes nas rotas do desafio Railway Tycoon.",
  [211107843548160] = "Ganhe Super Armadura",
  [870883807732224] = "Alterar posição",
  [1059930014489344] = "Canalização Interação",
  [1059930014488320] = "Sair da transformação",
  [211107038493952] = "Chefe Invencibilidade e inalvejável durante Cutscene",
  [1003167995170560] = "Poder da Arma: Iniciar",
  [1059930014487296] = "Veículo de Combate a Bordo",
  [752067564368384] = "Monstro Aéreo de Posicionamento Central",
  [1165565540455680] = "Fale com o NPC: O jogador toca uma música emocionante (audível apenas para ele).",
  [1059930014485248] = "Caindo",
  [224645311645184] = "Ângulo de inclinação extra",
  [1219153578954240] = "Licença de distribuição insuficiente, aguarde uma resposta",
  [497117768455424] = "Adicionar briga de clube",
  [409232268680960] = "Abaixo da coroa, está vazio, mas inúmeras pessoas parecem chorar em voz baixa.",
  [862018190282496] = "O melhor café da manhã",
  [1046805668222976] = "Durante o combate, tente o seu melhor para <Highlight> evitar ataques em área de efeito </> . Se alguém é reprimido, ele precisa de <Highlight> cura contínua </>.",
  [1046805668222720] = "O Beyonder alvo de <Highlight> [Hunt] </> deve usar continuamente <Highlight> [Regain Composure] </> para se libertar do controle. Beyonders deve rapidamente <Highlight> mudar o fogo para o Aberrant Manservant </>. O detentor do [Bell] deve se aproximar da Scarlet Hound Soul e usar a habilidade <Highlight> [Ring Bell] </> para transferir seu alvo de ataque para o Alienated Hound. Quando 2 Scarlet Hound Souls atacarem com sucesso o Alienated Hound, o Alienated Hound ficará <Highlight> paralisado por 10 segundos </>.",
  [858032191833600] = "Corredor das Glicínias",
  [1046805668222464] = "Atraia a Alma do Cão Escarlate para a Armadilha do Urso e derrote-a para derrubar o item selecionável <Highlight> [Bell] </> .",
  [1046805668221952] = "Guie a bola elétrica para dentro da poça de raios para formar uma poça de raios e, em seguida, atraia a \"Broca\" para a poça de raios para empilhar 4 camadas de sobrecarga para atordoá-la.",
  [1046805668221440] = "Transmita relâmpagos do Farol Sagrado Condutor ativado para carregar todos os faróis e quebrar a barreira de isolamento.",
  [1046805668221184] = "Atraia o \"Drill\" para entrar no raio e empilhar 4 camadas de sobrecarga para atordoá-lo.",
  [1046805668220928] = "Preste atenção ao sentido de rotação do raio e salte a tempo de evitá-lo.",
  [1046805668219904] = "Beyonders precisa <Highlight> encontrar esses 4 dançarinos e derrotá-los </>, então ficar nas posições originais dos 4 dançarinos para <Highlight> dançar </> , continuando o revezamento de dança. Beyonders que possuem a <Highlight> mesma habilidade de dança </> precisam ir para a <Highlight> formação de dança e dançar </>.",
  [1046805668219648] = "Beyonders que possuem a dança correspondente </> para <Highlight> precisam ficar na frente deste dançarino <Highlight> e dançar </> para bloquear </> o ataque de colisão do dançarino <Highlight> .",
  [1046805668218880] = "Concentre sua força para quebrar <Highlight> todos os destroços de guerra </> . Cada Beyonder precisa <Highlight> completar a coleta de energia de conquista </> e interagir com as runas para iniciar a oração.",
  [1046805668218112] = "Beyonders precisa <Highlight> encontrar esses 4 dançarinos e derrotá-los </>, então executar <Highlight> uma dança </> nas posições originais dos 4 dançarinos para retransmitir a dança.",
  [1046805668217856] = "Beyonders <Highlight> que possuem uma dança </> precisam entrar na formação de dança <Highlight> correspondente para dançar </>.",
  [1046805668217600] = "Beyonders precisa interagir com 6 <Highlight> Dançarinos </> para obter <Highlight> habilidades de dança temporárias </> para evitar danos.",
  [1046805668217344] = "Beyonders precisa <Highlight> entrar na área runa </> para ativá-lo.",
  [1046805668217088] = "Beyonders precisa <Highlight> entrar na área rúnica </> para ativá-lo. Preste atenção ao observar a runa <Highlight> Sequência </> e ative-as na ordem correta.",
  [1046805668216832] = "O <Highlight> Guerreiro </> precisa prestar atenção ao momento em que a Habilidade Finalizador atinge o Dragão Gigante. Outros Beyonders devem <Highlight> ficar longe do </> caminho de movimento do Dragão Gigante.",
  [440012688590848] = "Tire uma foto no local designado na Igreja do Rio e do Mar",
  [1046805668216320] = "O Beyonder alvo deve <Highlight> mover-se para a borda do campo </> para evitar afetar o campo de batalha central.",
  [440012957029376] = "\"O velho Neil sabe tocar piano?\"",
  [1046805668216064] = "Use a habilidade <Highlight> Cordeiro Guia </> para ajudar os sacrifícios <Highlight> a escapar da zona de perigo </> e imediatamente <Highlight> curar </> os sacrifícios com pouca saúde!",
  [440013225463808] = "Passado de Velhos Amigos (I)",
  [1046805668215808] = "Guie os sacrifícios para a área segura <Highlight></>. Assim que um número suficiente de sacrifícios for resgatado, Johnny cairá em um estado enfraquecido.",
  [440013493898240] = "A família Moretti decide se mudar para 2 Daffodil Street, \nviajando entre Daffodil Street e Iron Cross Street uma e outra vez, \neles riem da poeira cinzenta e das manchas sujas no rosto um do outro.",
  [1046805668215552] = "Guie o sacrifício para longe do perigo, e somente <Highlight> matando o demônio </> a tempo o ritual poderá ser interrompido!",
  [1046805668215296] = "Rapidamente <Highlight> reúna-se para compartilhar os danos </>. Após o compartilhamento, <Highlight> observe o status da conexão </> e <Highlight> evite correr e quebrar a conexão </>.",
  [1046805668215040] = "Rapidamente <Highlight> reúna-se para compartilhar os danos </>.",
  [1046805668214784] = "A <Highlight> classe de proteção </> precisa ficar na <Highlight> frente de Riel Bieber </> , ativar habilidades de redução de dano e bloquear o dano de raio para outros jogadores. <Highlight> As classes de cura </> também devem prestar atenção à saúde da classe de proteção.",
  [1046805668214528] = "A <Highlight> classe de proteção </> precisa ficar na <Highlight> frente de Riel Bieber </> para bloquear danos de raios para outros jogadores.",
  [1046805668214272] = "Observe atentamente os balões de slogan acima de sua cabeça e rapidamente fique na <Highlight> área antifraude </> . Após o término da contagem regressiva, a zona de perigo <Disable> explodirá e reduzirá significativamente a saúde </> .",
  [1046805668214016] = "Use a torre de dinheiro para <Highlight> disparar projéteis aprimorados em linha reta </> para quebrar o escudo com eficiência.",
  [879957194574592] = "O jovem Vigia Noturno Neil e a afinadora de piano Celeste se conhecem em um encontro às cegas. Desde o estranho reencontro no café até os passeios tranquilos pelo corredor das glicínias, seus corações gradualmente se aproximam. Porém, a doença tira a vida de Celeste, deixando Neil enfrentando o inverno sozinho. Muitos anos depois, o velho Neil ainda tenta encontrar aquela primavera verde-clara, mesmo ao custo de sua vida. No final, cartas antigas e um piano de madeira trazem a primavera de volta. Nesse casamento ilusório, os amantes nunca mais se separarão.",
  [1046805668213760] = "Use <Highlight> Gold Coin Toss </> para dar aos pobres moedas de ouro racionais o suficiente. Os pobres recuperarão sua racionalidade e <Highlight> se transformarão em nossa facção para ajudar na batalha </>.",
  [1046805668213504] = "Rapidamente <Highlight> vá para a área do palco </> , <Highlight> observe a direção do movimento do parceiro de dança </> , siga a <Highlight> direção correta para se mover </> e evite as explosões no solo sob seus pés. <Highlight> Ficar parado ou se mover na direção errada é muito perigoso </> !",
  [1046805668213248] = "Os jogadores precisam rapidamente <Highlight> concentrar o fogo no garçom </> , então <Highlight> se aproximar do carrinho de comida </> . Depois de pegar o bolo, <Highlight> jogue o bolo para atacar </> o Príncipe Sapo, ou <Highlight> empurre o carrinho para impactar </> o Príncipe Sapo.",
  [1046805668212992] = "Os jogadores precisam <Highlight> controlar bem a distância entre si </> e evitar vários danos de área de efeito enquanto estiverem no estado vinculado.",
  [1046805668212736] = "Os jogadores precisam <Highlight> mover-se ativamente para o caminho </> quando um companheiro de equipe está sendo cobrado para compartilhar o dano.",
  [1046805668212480] = "O jogador que está sendo caçado deve <Highlight> atrair o Cavaleiro Maçã para pisar na armadilha de urso </> ; outros jogadores devem <Highlight> concentrar o fogo nas armadilhas para ursos no campo </> para torná-las ativáveis; depois que o Apple Knight cair, não se esqueça de <Highlight> pegar o martelo para carregar </> .",
  [1046805668212224] = "Cada área segura dos anões <Highlight> só pode abrigar uma pessoa </>. Os jogadores precisam <Highlight> planejar suas posições com antecedência </> e entrar no círculo de maneira ordenada.",
  [1046805668211968] = "Os Anões levantarão um amplo escudo protetor. Todos os jogadores devem se esconder rapidamente no escudo protetor e <Highlight> ficar dispersos dentro do escudo protetor </> .",
  [1046805668211712] = "Depois que os jogadores se transformarem em maçãs que estão prestes a explodir, duas <Highlight> áreas seguras para anões </> serão geradas no campo. Os jogadores que se transformaram em maçãs devem <Highlight> se esconder rapidamente na área segura </> para evitar ferir acidentalmente seus companheiros de equipe.",
  [1046805668211200] = "Preste atenção ao seu próprio nível de corrosão da Marca Maligna <Highlight></> e evite deixá-lo acumular até 100%.",
  [1046805668210944] = "Os jogadores devem <Highlight> pular </> para <Highlight> tocar </> no meteoro antes que ele caia para evitar que ele atinja o solo.",
  [1046805668210688] = "Quando Karl Edgar pisar na “Evil Eye Trap”, o processo de absorção de poder será interrompido. O jogador rastreado deve <Highlight> atrair o monstro para pisar na armadilha </> .",
  [1046805668210432] = "Depois de serem selecionados como alvo do Olhar, os jogadores devem encontrar a estante de livros mais próxima e se esconder atrás dela, <Highlight> deixando a estante ajudá-los a bloquear o ataque de laser bloqueado </> .",
  [1046805668210176] = "Os jogadores devem <Highlight> afastar-se uns dos outros </> quando o aviso aparecer e planejar razoavelmente <Highlight> os locais de aparecimento das estantes de livros </> .",
  [1046805668209920] = "De acordo com os movimentos do Dancing King Baboon Brother, escolha a habilidade de dança correspondente para acompanhar a batida do Dancing King.",
  [1046805668209664] = "Os jogadores precisam se esquivar dos ataques do Dancing King Baboon Brother enquanto pegam notas musicais para ganhar Dance Power.",
  [1046805668209408] = "Durante esta fase, os jogadores devem trocar de alvo e matar <Disable> pelo menos dois pequenos babuínos </> antes que a contagem regressiva termine para obter todas as notas musicais. Em seguida, siga as instruções da partitura para <Disable> pegar as notas na ordem </> para completar a mecânica.",
  [1046805668209152] = "Os jogadores devem observar a cor de suas próprias notas musicais e caminhar até a <Disable> pista de dança da cor correta </> antes que o cronômetro termine para reduzir o dano sofrido.",
  [1046805668208896] = "Os jogadores alvo devem se esconder atrás dos pilares de pedra na arena para atrair o Rei da Dança e fazê-lo <Disable> colidir com o pilar </> , fazendo com que ele fique atordoado.",
  [1046805668208640] = "Os jogadores devem observar a posição das ondas sonoras de alerta e esquivar-se em uma determinada ordem <Highlight></> para evitar serem atingidos pelo impacto da energia.",
  [505845141997568] = "Distrito Universitário de Tingen",
  [1046805668208128] = "Observe o aviso de curva <Highlight></> e o aviso de posição inicial <Highlight></>. É recomendado parar de atacar e focar em se mover para se esquivar.",
  [1046805668207872] = "Observe a posição do Golem de Terra e sua ação inicial. Julgue o <Highlight> alcance de ataque subsequente </> e mova-se para se esquivar.",
  [1046805668207616] = "Os alcances dos dois ataques definitivamente não serão os mesmos. <Highlight> Observe o prompt de alcance de ataque inicial </> e mova-se para esquivar.",
  [1046805668207360] = "Todos deveriam se dispersar e usar <Disable> Purificação de Videira Baseada em Cogumelo </> para purificar a <Disable> Videira Murcha da Desolação </> mais próxima deles. Durante este período, você não poderá ser curado, portanto evite a área poluída.",
  [457604069330688] = "Noite de inverno do penhasco branco",
  [1046805668207104] = "Observe a posição de aparência do <Disable> Cogumelo Estéril </> e julgue a área segura, enquanto manuseia a dispersão e a mecânica de coleta dentro da área segura.",
  [1046805668206848] = "O jogador alvo deve se afastar rapidamente de Sylvia e eliminar o efeito da maldição <Disable> Blooming Mushroom </>, então entrar no escudo protetor para se defender contra a habilidade <Disable> Vitality Descent </>. Para cura em escudos de nível não mais alto, preste atenção à cura contínua. As classes que sofrem danos também precisam ativar a redução de danos do grupo e as habilidades de escudo nos momentos apropriados.",
  [1046805668206592] = "Desvie dos ataques de Sylvia e preste atenção à contagem regressiva do seu próprio efeito <Disable> Harvest Time </>. Ajuste sua orientação quando estiver prestes a terminar para evitar pulverizar colegas de equipe.",
  [1046805399738880] = "O Avatar Amon sai de campo e se transforma em milhares de Avatares Amon, <Disable> lançando um ataque coletivo </> aos jogadores.",
  [1046805399755264] = "O usuário do Astrolábio aprisiona um jogador através da <Disable> Restrição de Conhecimento </> e irradia dano ao ambiente. Se a restrição não for <Disable> quebrada </> dentro do prazo, o jogador <Disable> morrerá </> .",
  [1046805668206336] = "Ajuste a orientação de mira retangular para impactar a <Disable> Vinha da Abundância </> , enfraquecendo-a em vinhas verdes. Aproximar-se das videiras verdes fará com que você fique preso, evitando o efeito de repulsão de <Disable> Bounty of Abundance </> .",
  [1046805668206080] = "6 jogadores precisam se aproximar do <Disable> Mushroom Warrior </> e atraí-lo para longe da multidão, mantendo a área poluída longe da área de combate. Quando todos os <Disable> Mushroom Warriors </> forem atraídos com sucesso, todos ganharão um buff de 2 minutos que aumenta o dano em 200%.",
  [1046805668205824] = "Fungos podres podem ser atraídos para se mover; quando aparecem vinhas murchas, elas precisam ser focadas e tratadas o mais rápido possível.",
  [1046805668205568] = "Precisa julgar a área de bombardeio de meteoros subsequente e mover-se para se esquivar nas lacunas entre os bombardeios.",
  [1046805668205312] = "Julgue a direção da Respiração, ajuste sua posição e desvie do Campo de Feitiço poluído no caminho. Tocar no orbe de luz verde pode conceder imunidade a efeitos de repulsão.",
  [453076636935424] = "Desbloqueado após obter o traje Golden Branch Forest Shadow",
  [1046805668205056] = "Preste atenção à orientação do avatar espiritual e aos efeitos do alerta.",
  [1046805668204800] = "Preste atenção à velocidade e área dos ventos alísios.",
  [1046805668204288] = "Os jogadores guiam a tartaruga gigante para <Highlight> atacar em direção ao Castelo Rosa </> para fazer a tartaruga gigante cair e ficar atordoada.",
  [1046805668204032] = "Os jogadores podem usar o fato de que o veneno de cogumelo se dissolve na água para permitir que <Highlight> Calamity Water caia sobre o veneno de cogumelo para eliminá-lo </> . Quando o Castelo Rosa cai, ele pode se encher com Água da Calamidade; <Highlight> use o Castelo Rosa para eliminar a Água da Calamidade </> .",
  [1046805668203776] = "Os jogadores devem pegar o casco da tartaruga e usar a habilidade temporária de <Highlight> ativar Rock Armor </> para bloquear o impacto da Tartaruga Gigante.",
  [1046805668203520] = "Os jogadores devem observar a posição das Ondas do Mar e esquivar-se em uma certa <Highlight> ordem </> para evitar serem atingidos pelas Ondas do Mar.",
  [1046805668203264] = "Os jogadores devem ficar com o Cogumelo Venenoso e usar a habilidade da bola de água <Highlight> para eliminar o Cogumelo Venenoso </> para destruí-lo.",
  [1046805668203008] = "Jogadores segurando o <Highlight> Pulseira de Quatro Folhas </> devem ativar o <Highlight> Escudo da Sorte </> quando o ataque da Viscondessa estiver prestes a terminar para bloquear o Veredicto de Morte da Viscondessa.",
  [1046805668202496] = "Os jogadores devem matar todos os Butlers. Assim que o botão <Highlight> Espiritualidade Infusão </> aparecer no Pequeno Visconde, reúna-se para ajudar o Pequeno Visconde a ativar o escudo para bloquear a Viscondessa.",
  [1178677538719744] = "Salve-me",
  [1046805668201984] = "Os jogadores que possuem a <Highlight> Gema da Folha Verde </> devem usar a habilidade temporária para transferir a energia da gema para o jogador que possui a Pulseira de Quatro Folhas. Quando a transferência de energia atinge 3 camadas, o jogador segurando a <Highlight> Pulseira de Quatro Folhas </> deve ativar o <Highlight> Escudo da Sorte </> quando o ataque da Viscondessa estiver prestes a terminar para bloquear o Veredicto de Morte da Viscondessa.",
  [1046805668201728] = "Os jogadores que possuem a Marca de Lealdade devem <Highlight> se reunir </> e ficar longe dos outros jogadores, aguardando a execução da Viscondessa. Jogadores segurando <Highlight> 2 camadas de Little Viscount's Longing </> criarão um círculo de luz ao seu redor. Outros jogadores devem seguir o jogador com o buff Longing do Pequeno Visconde de 2 camadas para <Highlight> encontrar a obsessão do Pequeno Visconde </> e dissipar a escuridão.",
  [998838668109825] = "Lendário",
  [1046805668201472] = "Os jogadores que tocarem na obsessão do Mordomo serão vinculados. Os companheiros de equipe precisam <Highlight> trocar de alvo imediatamente para atacar o Mordomo </> . Após ser resgatado, o jogador ganhará uma <Highlight> Marca de Lealdade </>. A marca empilha até 3 camadas; quando atingir 3 camadas, explodirá. Posteriormente, a Viscondessa realizará uma <Highlight> Caça aos Fantasmas </> nos jogadores que possuem a marca. Os jogadores que tocarem na obsessão do Pequeno Visconde ganharão <Highlight> Saudade do Pequeno Visconde </>. Quando atingir 2 camadas, trará um brilho de luz na cena escura, e você poderá ouvir o chamado do Pequeno Visconde na escuridão, ajudando os jogadores a dissipar a escuridão.",
  [1046805668200960] = "Os jogadores que adquiriram características misteriosas no estágio inicial precisam ir até a borda do campo para <Highlight> eliminar os Alabardeiros </> para obter a Prova de Glória, enquanto outros jogadores saem com cautela no campo interno. Posteriormente, quando o duelo começar, os jogadores que possuem <Highlight> Prova de Glória de Nível 3 </> devem ir para o ponto de duelo <Highlight> para desbloquear a habilidade de duelo </> e então usar a habilidade para iniciar o duelo! Os jogadores restantes devem <Highlight> trabalhar juntos para quebrar </> o escudo da Armadura Ancestral para ajudar o duelo a ter sucesso!",
  [1046805668199936] = "Depois que os corpos espirituais esperando para serem revividos aparecerem, os jogadores que estão curando devem <Highlight> priorizar a cura dos corpos espirituais esperando para serem revividos </> , enquanto os outros jogadores mantêm sua produção.",
  [1125902054331136] = "Bloqueio de porta um pouco assustador",
  [1099582763189504] = "Fale com a pessoa em frente ao \"Gato\".",
  [1046805668198912] = "Organize-se em duas equipes para <Highlight> ajudar os dois jogadores alvo a compartilhar o dano respectivamente </> ; jogadores que já participaram do primeiro compartilhamento deverão evitar participar novamente.",
  [1046805668197376] = "Os jogadores que não são alvos devem <Highlight> se reunir ativamente em direção ao jogador alvo </> para ajudar a compartilhar o dano de Pressão.",
  [998838668109826] = "Épico",
  [1046805668197120] = "Preste atenção para evitar danos continuamente.",
  [1046805668196864] = "Os jogadores que curam devem <Highlight> prestar atenção à cura de todo o grupo </>, e todos os membros devem ativar habilidades de <Highlight> Redução de Dano </>.",
  [1046805668196608] = "Os jogadores visados ​​pelo Cão de Caça precisam <Highlight> se afastar ativamente da multidão </> . Outros jogadores devem trocar de alvo imediatamente para resgatá-los após o jogador ser atingido.",
  [1046805668196352] = "Você precisa <Highlight> concentrar o fogo para quebrar alguns dos núcleos das frutas </> e permanecer em uma área segura até que todos os núcleos das frutas explodam e morram.",
  [1046805668196096] = "Preste atenção na contagem regressiva </> de Anthea, pare de se mover no tempo e desvie das borboletas azuis e do caminho da boneca no campo. Aproveite bem as borboletas douradas para acelerar.<Highlight>",
  [1046805668195840] = "Fique longe das borboletas azuis e faça uso razoável das funções das borboletas douradas.",
  [1046805668195584] = "Durante o movimento, você deve atrair Anthea para <Highlight> ficar continuamente longe do </> Sr. Barney.",
  [998838668109827] = "Cru",
  [1046805668194560] = "Preste atenção na contagem regressiva </> de Anthea, pare de se mover no tempo e desvie das borboletas azuis no campo.<Highlight>",
  [1046805668194304] = "Depois que eles aparecerem, interrompa a conexão o mais rápido possível.",
  [1046805668194048] = "Fique longe das borboletas azuis.",
  [1046805668193792] = "Se a direção do traço <Highlight> o aproximar de </> Anthea, você deve atrair Anthea <Highlight> para longe de </> aquela posição.",
  [1214411935058176] = "%s - Promoção Peixe Fresco",
  [571816376537344] = "Explosão de Conhecimento Proibido",
  [1046805668193280] = "São necessários <Highlight> dois jogadores </> para atrair os ameaça do Sr. Barney e Anthea em lados opostos da arena, tentando <Highlight> mantê-los distantes </> .",
  [1046805668193024] = "Priorize a coleta de Starlight. Tente <Highlight> atacar </> o Usuário do Astrolábio e o Guarda da Luz Estelar simultaneamente e garantir que o transporte da Luz Estelar seja concluído.",
  [1046805668192768] = "O <Highlight> tempo em que </> jogadores podem armazenar Starlight temporariamente é limitado; você deve concluir o transporte o mais rápido possível.",
  [1046805668192512] = "A <Highlight> Onda de explosão </> gerada pela descida do Starlight Guard pode ser evitada <Highlight> saltando </> . Mude imediatamente os alvos para atacar e certifique-se de que o <Highlight> Guerreiro </> atraia os ameaça da Guarda da Luz Estelar. Depois de derrotá-lo, transporte rapidamente a Starlight para o Starlight Candlestick para mantê-la em segurança.",
  [1046805668192256] = "Quando colocado na frente do usuário do Astrolábio, <Highlight> afaste-se rapidamente do </> usuário do Astrolábio.",
  [211107844425984] = "Levemente Equipado: Redução de Dano +15%.",
  [1046805668191232] = "Quando um meteorito aparecer, <Highlight> afaste-se rapidamente </> da sua posição atual.",
  [1046805668190976] = "<Highlight> Reúnam-se </> para evitar ficarem muito espalhados, o que tornaria a área de efeito do míssil muito grande para ser esquivada.",
  [1046805668190720] = "O jogador alvo deve se mover em direção ao usuário do Astrolábio. Outros jogadores devem trocar de alvo rapidamente quando a <Highlight> Restrição </> aparecer e prestar atenção à saúde do time.",
  [1046805668190464] = "O jogador alvo deve <Highlight> mover-se para guiar a direção do ataque Earth Tremor </> para evitar afetar muitos companheiros de equipe.",
  [1046805668190208] = "Cada Leaping Slash requer <Highlight> pelo menos 4 pessoas para reunir </> para compartilhar o dano. Além disso, os jogadores que compartilham a primeira instância de dano <Highlight> não podem participar da segunda instância de compartilhamento </> no curto prazo.",
  [1046805668189952] = "<Highlight> A Corner of Mysteries: abre na segunda-feira </> \n <Highlight> Wailing Black Market: abre na terça/sexta </> \n <Highlight> Sin of Gold: abre na quarta/sábado </> \n <Highlight> Traces of the Dead: abre na quinta/domingo </>",
  [1046805668189696] = "Concentre o poder de fogo da equipe para <Highlight> quebrar um canto da Prisão de Gelo </> para quebrar a prisão e escapar do alcance do ataque letal.",
  [1112913536360960] = "Sequência 8: Buscador de Luz",
  [1046805668189184] = "Você deve passar pela Parede de Visão ou evitar ser escaneado por ela enquanto 2-049 <Highlight> estiver com os olhos fechados </> .",
  [1046805668188928] = "A <Highlight> classe de proteção </> precisa afastar Riel Bieber <Highlight> imediatamente de 2-049 </> .",
  [1046805668188672] = "Os jogadores afetados pela <Highlight> Estagnação </> terão um botão aparecendo neles. <Highlight> Clique no botão </> para remover a <Highlight> Estagnação </> daquele jogador.",
  [1046805668188416] = "[Em construção] Dicas de resposta de fase",
  [1046805668188160] = "<Highlight> Observe a posição inicial e o sentido de rotação dos raios para evitar tocá-los </> . Ao evitar os raios, lembre-se de bloquear a Energia do Caos.",
  [1046805668187904] = "<Highlight> Colete os espiritualidade fragmentos espalhados na Cidade de Prata e leve-os para a área de carregamento para carregar o Abrigo de Prata. </> Dentro da área totalmente carregada, você pode ficar imune a uma instância de dano devastador.",
  [1046805668187648] = "<Highlight> Troque os alvos para os Sacrifice Phantoms o mais rápido possível </> . Não deixe nenhum fantasma tocar em Sasrir.",
  [1046805668187392] = "<Highlight> Bloqueie ativamente a Energia do Caos, prestando atenção na cor do seu próprio destino. Colidir com energia da mesma cor do seu destino fará com que você fique atordoado. </> Não deixe a energia tocar Sasrir.",
  [1046805668187136] = "Os jogadores alvo devem <Highlight> ficar longe do grupo principal, colocar a água preta na borda do campo </> e sair o mais rápido possível.",
  [1046805668186880] = "<Highlight> Observe o ritmo da maré do rio </> para atravessar quando o rio estiver calmo e evite-o quando estiver prestes a entrar em erupção.",
  [1046804594428928] = "Plataforma giratória",
  [1046805668186624] = "Todos devem <Highlight> mover-se com flexibilidade </> para se esquivar enquanto designam jogadores específicos para <Highlight> bloquear a linha </> . Os jogadores restantes devem imediatamente <Highlight> mudar de alvo para atacar </> e destruir a estátua que perdeu sua invencibilidade para forçar Milgongen a um estado de Quebra de Armadura.",
  [1046805668186368] = "Reserve <Highlight> habilidades de finalização </> para liberar quando a armadura de Milgongen for quebrada para causar mais dano.",
  [1108652123491328] = "Origem",
  [1046805668185856] = "Evite entrar no círculo mágico da estátua <Highlight></> para sofrer dano de área.",
  [1046805668185600] = "Organize de forma flexível para que os jogadores <Highlight> interceptem </> os raios laser.",
  [1046805668185344] = "Quando o efeito de invencibilidade da estátua desaparecer, <Highlight> destrua </> a estátua imediatamente.",
  [1046805668185088] = "O dano da Onda de Choque pode ser evitado <Highlight> saltando </> .",
  [563294624549120] = "4º ao 10º lugar",
  [1046805668184832] = "As bolas de fogo solares representam uma ameaça fatal para os jogadores. Você deve <Highlight> direcionar tiros de lança </> contra eles para reduzir a pressão de saúde a tempo.",
  [1046805668184576] = "<Highlight> Guie os soldados da legião para colidirem entre si </> .",
  [514641771945984] = "Iniciar análise de desempenho; entrar no modo.",
  [1046805668184064] = "<Highlight> Concentre os ataques na cadeira de encosto alto </> para resgatar o companheiro de equipe preso.",
  [440562175974656] = "Abrigo do Codex · V",
  [1046805668183808] = "Dentro do tempo limitado, faça contato com um companheiro de equipe de <Highlight> destino oposto </> .",
  [1046805668183552] = "Identifique os inimigos usando o <Highlight> Fate Halo </> e <Highlight> atacando inimigos com destino oposto ao seu </> .",
  [1046805668183296] = "Os jogadores precisam derrotar Medici e Ouroboros simultaneamente dentro de <Highlight> 10 segundos </> .",
  [580887347478528] = "Momento do Destino · Triunfante",
  [580887347470336] = "Batalha pelo Trono de Deus · Governante",
  [1046805668183040] = "<Highlight> Texto chave </> Texto normal texto normal texto normal.",
  [1046805668182784] = "Usar <Highlight> Morte Artificial </> pode dissipar o efeito <Highlight> Luz Negra </> de todos os jogadores próximos.",
  [1046805668182528] = "Os <Highlight> corpo espiritual threads </> serão quebrados quando a distância entre as duas partes conectadas <Highlight> exceder um determinado valor </> . Os jogadores precisam correr na direção oposta do outro jogador conectado.",
  [1046805668182272] = "Use <Highlight> Grey Fog Perception </> para detectar a localização dos <Highlight> Demon Wolf Kin </> e trocar de alvo para atacá-los. <Highlight> Storm Prayer </> pode atordoar os <Highlight> Demon Wolf Kin </>, tornando-os temporariamente visíveis e fazendo com que percam sua capacidade de atacar e se mover.",
  [1046805668182016] = "Use <Highlight> Grey Fog Perception </> para detectar a localização da <Highlight> Dark Shadow </> e encontrar lacunas para evitar ataques.",
  [1046805668181760] = "Use <Highlight> Grey Fog Perception </> para detectar a localização das estátuas do Demon Wolf e destruir todas elas antes que o Dark Devour consuma o campo. <Highlight> Storm Prayer </> também pode quebrar as estátuas. Ao mesmo tempo, certifique-se de usar <Highlight> Morte Artificial </> para dissipar o efeito Dark Light aplicado pelo Dark Demonic Wolf.",
  [1046805668181504] = "Concentre todo o fogo no vórtice histórico <Highlight> da área sem sombra </> e mova-se para uma nova área sem sombra no tempo após a reversão do espaço-tempo.",
  [1046805668181248] = "Observe a direção do movimento do orbe de luz para encontrar e focar o fogo no Avatar Amon em tempo hábil no ponto de pouso final do orbe <Highlight></> .",
  [1046805668180992] = "O jogador Curador deve <Highlight> curar continuamente o jogador parasitado </> , enquanto outros jogadores concentram o fogo no chefe .",
  [1046805668180736] = "Quando a contagem regressiva da explosão termina, os dois jogadores alvo precisam <Highlight> designar uma pessoa para entrar na área de sombra </> para evitar que as duas ocorrências de dano causem uma limpeza em grupo.",
  [1046805668180480] = "Os jogadores perseguidos pela onda devem <Highlight> conduzir a onda para a área de sombra o mais rápido possível </> .",
  [1046805668180224] = "O jogador Tank precisa <Highlight> puxar o Avatar Amon para fora da área de sombra </> ; outros jogadores devem ser cautelosos ao entrar na área sombreada.",
  [1046805668179712] = "Mude os alvos para <Highlight> Filthy Cub </> a tempo e empurre o filhote para baixo de Gulu <Highlight> para ser devorado por Gulu </> , controlando assim o crescimento do Valor da Fome.",
  [1046805668179456] = "O <Highlight> jogador de cura </> deve liberar habilidades de cura em grupo a tempo.",
  [1046805668179200] = "Todos deveriam <Highlight> pular </> a tempo de evitar a onda de choque.",
  [440562712843521] = "Conclua 15 \"Baús do Tesouro Misterioso\"",
  [1046805668178944] = "O jogador alvo deve <Highlight> ativar a redução de dano </> a tempo, e os outros devem ter cuidado para <Highlight> ficar longe </> da localização do jogador alvo.",
  [1046805668178688] = "Todos, prestem atenção em <Highlight> se mover com flexibilidade </> para se esquivar.",
  [1046805668178432] = "<Highlight> Destrua todas as projeções o mais rápido possível </> para interromper a pesquisa do Palhaço.",
  [1046805668178176] = "Observe o naipe de cartas <Highlight></> acima de sua cabeça e rapidamente fique na área correspondente.",
  [1046805668177920] = "Observe a posição do companheiro de equipe alvo e <Highlight> entre no círculo para compartilhar o dano a tempo </>.",
  [1046805668177664] = "Mova-se com cautela para <Highlight> evitar que zonas de dano se sobreponham </> .",
  [1046805668177408] = "Todos os jogadores precisam passar pelo labirinto para chegar a Riel Bieber e <Highlight> remover a transformação de marionete </> .",
  [1046805668177152] = "Os jogadores precisam <Highlight> quebrar o escudo </> o mais rápido possível antes que Riel Bieber termine de ler.",
  [1046805668176896] = "Preste atenção aos avisos de solo e <Highlight> evite o ataque de Riel Bieber </> a tempo.",
  [329923549989376] = "Status atual: \t\"Dúvida\" <Tips> Clique no botão para ver os detalhes </>",
  [1046805668176640] = "Bolas de energia atingindo o carro causarão grandes danos; todos os jogadores da equipe devem tentar o seu melhor para <Highlight> bloquear as bolas de energia </> .",
  [1046805668176384] = "A <Highlight> classe DPS </> precisa eliminá-lo o mais rápido possível.",
  [1046805668176128] = "A <Highlight> classe DPS </> precisa eliminá-lo a tempo.",
  [1046805668175616] = "Use uma <Highlight> Control Break ou Displacement Skill </> para sair do centro da habilidade.",
  [1046805668175104] = "Use uma <Highlight> habilidade de quebra de controle </> para criar distância no tempo.",
  [1046805668174848] = "<Highlight> Fique longe do alcance de influência do Dragão da Imaginação </> .",
  [1046805668174592] = "<Highlight> Tenha cuidado para ficar longe de Audrey </> .",
  [1046805668174336] = "<Highlight> Preste atenção às trajetórias de movimento dos Avatares Amon </> e prepare-se para fugir com antecedência.",
  [1003099275661312] = "Compreender todos os princípios de atuação; a poção foi totalmente digerida dentro do corpo...",
  [1046805668174080] = "Siga as instruções na tela para reagir rapidamente e <Highlight> libertar-se do controle do Avatar Amon </> .",
  [1046805668173824] = "Os jogadores precisam <Highlight> afastar a Vontade Carmesim do luar </> .",
  [568104987934720] = "Em andamento",
  [1046805668173568] = "Arrodes invocará oportunamente uma barreira de neblina cinza; <Highlight> vá até lá o mais rápido possível para se proteger </> .",
  [382700108127488] = "Charme +5",
  [1046805668173312] = "Após a formação do cacho de flores, <Highlight> afaste-se rapidamente da vizinhança do cacho de flores </> .",
  [286219036545281] = "Retângulo de 15 metros de comprimento e 2,5 metros de largura",
  [286219036532993] = "Auto",
  [818111813509888] = "[Atuar como Adivinho]",
  [316868191919873] = "Operar caixão de pedra",
  [1046805668173056] = "Os jogadores precisam <Highlight> observar os avisos de habilidade </> e se preparar para fugir com antecedência.",
  [818111813174016] = "Atualizar Habilidade 1",
  [818111813206784] = "vou tentar também",
  [818111813010176] = "Sobre o Sr.",
  [818111813075712] = "Sonho de Angellwade",
  [818113155826944] = "Quero rescindir o contrato",
  [1046805668172800] = "Os jogadores precisam <Highlight> destruir a bola de energia </> o mais rápido possível.",
  [286219304963328] = "Quebra de Escudo",
  [1046805668172544] = "Os jogadores precisam <Highlight> espalhar </> o mais rápido possível para evitar sofrer <Highlight> múltiplas instâncias de dano de maldição </> .",
  [1046805668172288] = "Os jogadores precisam <Highlight> eliminar a Sombra </> o mais rápido possível; a Sombra eliminada criará uma <Highlight> zona segura </> .",
  [818113155646720] = "Muito extravagante",
  [1046805668172032] = "Os jogadores precisam <Highlight> mover-se com flexibilidade </> para evitar os pilares de gelo.",
  [1046805668171776] = "O <Highlight> jogador DPS </> precisa eliminar os lacaios o mais rápido possível.",
  [1046805668171520] = "Você precisa <Highlight> transferir a lesão </> a tempo; jogadores curandeiros <Highlight> prestam atenção à saúde dos companheiros de equipe </> .",
  [1161155682815232] = "Diálogo do vidente",
  [818113155220736] = "Sobre empréstimo de livros",
  [818113155294464] = "Ver arquivos ferroviários",
  [1218466115761664] = "Estátua de gesso",
  [1125969968798976] = "Vá até lá e explique para Lily",
  [1125969968717056] = "Aguarde a página do gatilho terminar",
  [818108054944512] = "Chloé",
  [1125969968504064] = "Veja o que é ‘Torta do Céu Estrelado’",
  [1125971310761728] = "Procure entre o <h> cadáver do soldado </>",
  [1125971310679808] = "Diga adeus a <h> Aiden </>",
  [1046805668169472] = "O <Highlight> jogador DPS </> precisa eliminá-lo o mais rápido possível.",
  [1046805668169216] = "O <Highlight> jogador tanque </> precisa segurar ameaça a tempo.",
  [1169959292161280] = "Jogar Diálogo. O jogador se teletransporta pelas cenas para o gatilho especificado.",
  [1130504917104896] = "Animação",
  [1046805399787008] = "Evoca 2 <Disable> Scarlet Hound Souls inalvejáveis ​​</> , que fixam e rastreiam continuamente um jogador cada. Uma vez capturado por uma Scarlet Hound Soul, o jogador sofrerá <Disable> alto dano de mordida </> .",
  [1046805399786496] = "Depois que \"Drill\" flutua, 6 <Highlight> Water Pools </> aparecem no campo. <Highlight> Bolas Elétricas </> aparecem ao redor de cada Beyonder , rastreando-as automaticamente. Os jogadores devem conduzir as <Highlight> Bolas Elétricas </> até as <Highlight> Piscinas de Água </> para transformá-las em <Highlight> Thunder Pools </> . Depois disso, \"Drill\" pousa e inicia cargas aleatórias contínuas! Beyonders deve evitar os <Highlight> Thunder Pools </> e atrair \"Drill\" para pisar nos <Highlight> Thunder Pools </> para adicionar stacks de <Highlight> Overload </> . Ao atingir 4 pilhas, ele entra em estado <Highlight> Atordoamento </>.",
  [1046805399785984] = "Depois que \"Drill\" flutua, ele invoca uma <Highlight> Barreira Isolante </> . Vários <Highlight> Farois Sagrados Condutores </> aparecem no campo, um dos quais está ativo. Todos Beyonders devem guiar os raios do farol ativo para carregar os outros faróis. Completar a carga quebrará a <Highlight> Barreira Isolante </> ; deixar de fazê-lo dentro de um determinado período de tempo resulta em em grupo apagamento.",
  [1046805399785728] = "Depois que \"Drill\" flutua, 6 <Highlight> Thunder Pools </> aparecem no campo. Lure \"Drill\" para carregar e pise em um <Highlight> Thunder Pool </> para adicionar pilhas de <Highlight> Overload </> . Ao atingir 4 pilhas, ele entra em estado <Highlight> Atordoamento </>.",
  [1046805399785472] = "\"Drill\" invoca raios que giram por um período de tempo antes de reverter. Ao mesmo tempo, um grande número de <Highlight> Campos Elétricos </> aparecem no campo, obstruindo caminhos. Ser atingido por um raio adiciona pilhas de <Highlight> Sobrecarga </> .",
  [1046805399784448] = "Bonnie irá convocar 10 projeções de dançarinos para dançar com ela, mas <Disable> 4 dos dançarinos </> estarão realizando uma dança diferente dos outros <Disable> diferente </> . Ao mesmo tempo, Bonnie irá convocar <Disable> 2 formações de dança </> ao seu redor. Depois de matar qualquer dançarino executando a dança errada, a formação será rotulada com um <Disable> nome de dança </> . Após um certo período, Bonnie verificará a dança de todos no campo e causará danos em todo o campo.",
  [1046805399784192] = "Bonnie invocará 3 <Disable> projeções de dançarinos </>. Cada dançarino exibirá um <Disable> nome de dança </> <Disable> acima de sua cabeça </> . A dançarina terá como alvo um Beyonder e, após um período de tempo, <Disable> traço </> naquele Beyonder .",
  [1046805399783424] = "Depois de voar, o War Dragon começa a carregar. Beyonders deve <Disable> destruir os fragmentos de guerra dentro de um tempo limitado, coletar Energia de Conquista e interagir com as runas correspondentes para completar a oração </>. Assim que <Disable> 6 Beyonders </> tiverem concluído suas orações, a Energia de Conquista reunida se transformará em uma força poderosa que derrubará o Dragão de Guerra do céu.",
  [1046805399782656] = "Bonnie irá convocar 10 projeções de dançarinos para dançar com ela, mas <Disable> 4 dos dançarinos </> estarão realizando uma dança diferente dos outros <Disable> diferente </> . Após um certo período, Bonnie verificará a dança de todos no campo e causará danos em todo o campo.",
  [1046805399782400] = "Bonnie irá convocar 3 <Disable> formações de dança </>. Cada formação será rotulada com um <Disable> nome de dança </> . Beyonders quem possui essa dança deve entrar na formação para dançar. Caso contrário, Bonnie causará danos em todo o campo para punir aqueles que perturbarem a ordem da pista de dança.",
  [1046805399782144] = "Bonnie invocará 6 <Disable> projeções de dançarinos </>. Os 6 bailarinos realizarão 3 tipos de danças. Após um pequeno atraso, Bonnie causará grandes danos a todo o campo.",
  [1046805399781888] = "Depois de voar, o Dragão de Guerra circulará o campo, deixando chamas para trás e carregando continuamente. Beyonders deve completar um ritual de oração usando as <Disable> 6 runas </> no campo dentro de um tempo limitado para derrubar o Dragão de Guerra. \n Beyonders pode ativar a runa correspondente inserindo seu alcance. Após o início do segundo ritual, as runas devem ser ativadas no <Disable> especificado Sequência </> , caso contrário o ritual não terá efeito.",
  [1046805399781632] = "Depois de voar, o Dragão de Guerra circulará o campo, deixando chamas para trás e carregando continuamente. Beyonders deve completar um ritual de oração usando as <Disable> 6 runas </> no campo dentro de um tempo limitado para derrubar o Dragão de Guerra.",
  [1046805399781376] = "O War Dragon trava em <Disable> 1 Beyonder </> e inicia uma investida. Durante a investida, um Guerreiro pode usar uma <Disable> Finisher Skill </> para interceptar e interromper com sucesso a investida do Dragão de Guerra.",
  [1046805399781120] = "O Dragão de Guerra se fixa em <Disable> 3 Beyonders </> e cospe bolas de fogo. Depois que as bolas de fogo pousam, elas explodem e deixam <Disable> zonas de chamas continuamente queimando </> no chão.",
  [1046805399780864] = "O Dragão de Guerra se fixa em <Disable> 1 Beyonder </> e cospe uma bola de fogo. Depois que a bola de fogo pousa, ela explode e deixa uma zona de chamas <Disable> brevemente queimando </> no chão.",
  [1046805399780608] = "Sacrifícios inocentes serão convocados periodicamente por Johnny para aparecer em cena. Quando um sacrifício é morto por Johnny, ele libera uma onda de choque em todo o campo.",
  [286219036541186] = "Atordoamento: Área circular com raio de 1,5 metros",
  [1046805399780352] = "Johnny convoca sacrifícios inocentes e inicia um jogo de matança, enquanto zonas seguras que podem salvar os sacrifícios aparecerão no campo.",
  [1046805399780096] = "Johnny convoca seis sacrifícios inocentes e leva os demônios a atacá-los, realizando um Ritual de Sacrifício.",
  [1046805399779840] = "Anthea irá convocar o Sr. Barney para liberar <Disable> em vários jogadores, o que requer compartilhar o dano do golpe </> . Após compartilhar, ela <Disable> selecionará aleatoriamente um jogador </> para ser vinculado ao jogador que compartilhou o dano <Disable></> . Uma vez que este link <Disable> seja quebrado </> , causará danos massivos a ambas as partes.",
  [409368633809920] = "Trigo de alto rendimento, cardumes de peixes gordos... O poder da Árvore da Abundância causou problemas para a Pequena Cidade do Outono Dourado, mas também tornou a cidade inesperadamente famosa como um \"modelo agrícola\". \n Todo semestre, estudantes das principais faculdades agrícolas do Reino de Loen iam para a cidade estudar, e alguns comentários estranhos sobre a Árvore da Abundância começaram a se espalhar, tornando-se gradualmente conhecidos por todos: \n \"Usar fertilizante abençoado pela Árvore da Abundância para cultivar significa que as colheitas não perdem nutrientes nem evaporam; um saco vale dois!\" \n Os alunos que retornaram da Golden Autumn Small Town ficaram maravilhados com as colheitas que cultivaram. No final do semestre, havia outro grupo de estudantes correndo para a Árvore da Abundância. \n A beira do lago estava repleta de teses de estudantes. Sob os galhos dourados havia escassas couves-flores, peixes murchos e até pessoas deitadas em macas em coma. Um companheiro se ajoelhou no chão com um baque surdo e gritou para a Árvore da Abundância: \"Socorro! Meu colega de quarto foi envenenado pela tese que ele vem cultivando há quatro anos!\" \n \"Oh, Árvore da Abundância! Por favor, abençoe meu colega de quarto e transforme seu trigo em uma variedade não tóxica!\"",
  [409368633826304] = "Uante, eu conheço você, um dramaturgo de segunda categoria, um “espectador” medíocre. Mesmo com Beyonder poder, você ainda permanece na avaliação secular, pensando que seu talento está além do alcance de qualquer pessoa. Você escreveu inúmeros manuscritos, esperando uma oportunidade para ser apreciado; você critica ruidosamente a vulgaridade dos dramas de sucesso; você tem ciúme das palavras desses autores; você odeia este mundo, mas deseja que os olhos do mundo inteiro se concentrem em você; você quer ficar satisfeito, não importa o preço. \n Sentar na plateia não é para você; Eu tenho um ritual que pode permitir que você ore aos deuses. Você só precisa agradá-Lo com uma morte suficientemente extravagante e será capaz de realizar o seu desejo.",
  [1046805399779584] = "Anthea convocará o Sr. Barney para lançar um ataque <Disable> compartilhável </> em vários jogadores.",
  [1046805399779328] = "Riel Bieber invoca o poder de suas notas, disparando um raio de energia contínuo que causa dano adiante. O raio causa dano ao <Disable> primeiro jogador que atingir </> e é bloqueado por ele. À medida que a habilidade continua, o <Disable> dano causado pelo raio aumentará gradualmente </>.",
  [1046805399779072] = "Riel Bieber invoca o poder de suas notas, disparando um raio de energia contínuo que causa dano adiante. O raio causa dano ao <Disable> primeiro jogador que atingir </> e é bloqueado por ele.",
  [1046805399778816] = "O campo é dividido em <Disable> 9 áreas </> , cada uma contendo projeções reais e falsas com pistas escondidas nos balões de fala acima de suas cabeças. <Disable> Apenas um deles é uma projeção benevolente que promove a conscientização antifraude </> .",
  [1046805399778560] = "Rock King constrói uma <Disable> Proteção da Dívida </> ; se não for destruído a tempo, irá desencadear uma <Disable> explosão em todo o campo </> . Ao mesmo tempo, <Disable> Money Turrets </> aparecerão nos bastidores.",
  [1046805399778304] = "Rock King espalha moedas de ouro pecaminosas para enfeitiçar um grande número de <Disable> pessoas empobrecidas </>. Uma vez enfeitiçados, a velocidade de movimento e o poder de ataque das pessoas empobrecidas <Disable> aumentam significativamente </>, e eles perseguirão os jogadores loucamente.",
  [1046805399778048] = "A hora predestinada chegou; todos devem participar juntos do grande baile. Os jogadores devem <Disable> ir para a área designada do palco </> e seguir as instruções de direção de movimento do <Disable> parceiro de dança </> para dançarem juntos. Mover-se na <Disable> direção errada resultará em penalidades correspondentes </> .",
  [1046805399777792] = "O Príncipe Sapo entra em um estado inalvejável, perseguindo continuamente Cinderela na tentativa de beijá-la; quando sua paciência acabar, ele atacará todos em um estado frenético. Garçons e carruagens aparecerão na borda do campo. Depois de <Disable> afugentar os garçons </> , os jogadores podem usar os <Disable> adereços do campo </> para atacar o Príncipe Sapo, quebrando sua defesa e derrubando-o.",
  [1046805399777536] = "Os jogadores serão amarrados uns aos outros <Disable> em pares </> por fios formados pela magia dos contos de fadas, tornando-se parceiros de dança. Uma vez que os parceiros <Disable> se afastem mais de 8m </> , eles serão <Disable> arrastados à força pela magia do conto de fadas e sofrerão grandes danos </> .",
  [1046805399777280] = "O Cavaleiro Maçã <Disable> ataca sucessivamente dois jogadores </> , causando <Disable> dano massivo compartilhável </> a todos em seu caminho.",
  [1046805399777024] = "O Apple Knight lança um Whirlwind Slash, <Disable> perseguindo continuamente os jogadores </> . Várias armadilhas para ursos aparecerão no campo; atrair o Apple Knight para <Disable> pisar em 3 armadilhas de urso irá derrubá-lo </>, permitindo que os jogadores usem o <Disable> martelo de guerra </> do Apple Knight para desferir um golpe fatal.",
  [1046805399776768] = "O Apple Knight invoca um grande número de Apple Bombs, preparando-se para <Disable> bombardear todo o campo </> . Anões chegarão de todas as direções para fornecer suporte, gerando Zonas Seguras para Anões em <Disable> locais diferentes </> .",
  [1046805399776512] = "O Cavaleiro Maçã espalha veneno pelo campo; após o término da contagem regressiva, ele <Disable> mata instantaneamente todos os jogadores </> . Ao mesmo tempo, uma semente venenosa é plantada em cada jogador, o que desencadeará uma <Disable> explosão de pequeno alcance </> após o término da contagem regressiva.",
  [1046805399776256] = "O Apple Knight seleciona dois jogadores, causando dano de área após um pequeno atraso, e <Disable> salta em um padrão cruzado para causar dano de área novamente </> . Os dois jogadores selecionados se transformarão em <Disable> maçãs explosivas </> , que detonarão e atingirão todo o campo após o término da contagem regressiva.",
  [1046805399775744] = "Quando o nível de corrupção da <Disable> Marca Maligna </> em um jogador chega a 100%, ele se transforma em um estado de <Disable> Dark Erosion </>. O jogador se transforma em um <Disable> Fantasma </> por um período de tempo, durante o qual ele não pode pular ou usar habilidades.",
  [1046805399775488] = "Abaddon lança um feitiço proibido, convocando um grande número de meteoros infundidos com energia maligna para cair do céu. Se um meteoro atingir o solo, ele explodirá, causando dano a todos os jogadores e aplicando um efeito de <Disable> Marca Maligna </>. Se um jogador pegar um meteoro antes que ele atinja o solo, ele só causará dano a esse jogador e aplicará um efeito de <Disable> Marca Maligna </>.",
  [1046805399775232] = "Karl Edgar folheia seu códice, absorvendo poder continuamente. Durante esse tempo, ele <Disable> rastreia continuamente um jogador </> e <Disable> os mata instantaneamente </> quando a absorção de poder termina. Além disso, todo o dano sofrido ao absorver poder é significativamente reduzido e ele pode causar dano contínuo a todo o campo. \n <Disable> O processo de absorção de energia pode ser interrompido por \"Evil Eye Traps\" </> .",
  [409365949453312] = "<CostRed> {1,3,(Marca expirada)} </> Ataque aumentado em <Mark> 345 </> , Defesa diminuída em <Mark> 10 </> , corrupção aumentada em <Mark> 15 </> . \nefeito de corrupção: Ao atingir <Mark> 30 </> de corrupção, a Defesa diminuiu em <Mark> 10 </> . <Mark> {1,4,（Purificado）} </> \nNão tem efeito quando o conjunto <Mark> Eco de Espírito e Conhecimento </> está ativo.",
  [409365949457408] = "Especialização em Monstro aumentada em <Mark> 130 </> . Ficar parado em combate por <Mark> 5 </> segundos diminui a Especialização de Monstro em <Mark> 25 </> por <Mark> 5 </> segundos; após uma Esquiva, a Especialização do Monstro é aumentada em <Mark> 25 </> por <Mark> 15 </> segundos.",
  [356586438594817] = "Fronteira da pupila",
  [356586438533377] = "Altura",
  [356586438529281] = "Comprimento do braço",
  [1046805399774976] = "Karl Edgar libera seu espiritualidade para manifestar os Olhos do Mistério Inquisitivo. Os jogadores observados pelos Olhos do Inquisidor Misterioso não têm onde se esconder e serão alvo do ataque a laser de Karl Edgar após um pequeno atraso. \n <Disable> Estantes de livros podem bloquear o ataque do laser </> , e serão destruídas com o impacto, transformando-se em <Disable> \"Evil Eye Traps\" </> .",
  [1046805399774720] = "Karl Edgar converte o infinito Conhecimento Proibido que ele extraiu em energia física, convocando estantes de livros condensadas do Conhecimento Proibido ao redor de cada jogador. Assim que um jogador <Disable> se aproximar de uma estante, ele será amaldiçoado </> e terá dificuldade para escapar.",
  [1046805399774464] = "O Dancing King Baboon Brother teletransporta os jogadores para o centro da pista de dança. Enquanto dança, ele <Disable> realiza diversas ações </> . Os jogadores devem seguir as instruções para executar as danças correspondentes. Uma vez que <Disable> o grupo cometa um total de 3 erros </> durante esta fase, o Irmão Babuíno ficará frustrado e irritado, causando <Disable> dano massivo </> aos jogadores.",
  [1046805399774208] = "Uma chuva de notas douradas começa a cair no campo. Depois de pousar no chão, os jogadores podem tocar nas notas douradas para acumular poder de dança. Acumule todo o poder de dança <Disable> antes que a contagem regressiva termine </> para ganhar uma <Disable> Barreira Musical </> ; caso contrário, o Irmão Babuíno causará <Disable> danos massivos </> aos jogadores.",
  [1046805399773952] = "O Dancing King Baboon Brother se teletransporta para o centro da pista de dança, levanta os braços e grita, desejando uma música mais poderosa, e convoca sua trupe de dança de babuínos. Os jogadores precisam <Disable> matar os pequenos babuínos </> para obter <Disable> notas caídas </> e pegar as notas de acordo com a <Disable> partitura musical Sequência </> .",
  [1046805399773696] = "O Dancing King Baboon Brother se teletransporta para o centro da pista de dança para dançar, pendurando <Disable> energia de notas de cores diferentes </> em cada jogador, enquanto convoca <Disable> três pistas de dança de cores diferentes </> no campo. <Disable> Depois que o cronômetro terminar </> , ele liberará energia elétrica para atacar todos os jogadores, causando dano massivo àqueles que caminharam para o andar errado.",
  [1046805399773440] = "O Dancing King Baboon Brother gradualmente fica animado, continuamente visando diferentes jogadores para atacar. Cada carga <Disable> causa dano de controle </> aos jogadores no caminho e deixa para trás um <Disable> caminho de fogo </> que causa dano contínuo.",
  [1046805399773184] = "No início da habilidade, o Dancing King Baboon Brother se teletransporta para o centro do campo para dançar, então libera 3 <Disable> habilidades de dano em grande escala </>, atacando cada jogador.",
  [1046805399772928] = "A Proteção da Prole extrai o poder das linhas ley através de um círculo de alquimia, frequentemente refinando Golems da Terra e lançando <Disable> Tremor da Terra </>.",
  [1046805399772672] = "Quando a Proteção da Prole estiver com <Disable> 50% de Vida </> , ela cairá em um estado de perda de controle, durante o qual o Golem ficará furioso, lançando frequentemente <Disable> Earth Tremor e Ley Line Resonance </> .",
  [1046805399772416] = "A Proteção da Prole refina um Golem da Terra, que irá replicar <Disable> Tremor da Terra </> ou <Disable> Ressonância da Linha Ley </> .",
  [1046805399772160] = "A Proteção da Prole extrai energia das linhas ley do pomar, detonando para causar <Disable> dano de área circular </> ou <Disable> de área anelar </>.",
  [1046805399771904] = "Sylvia entra em estado de colapso e invoca continuamente <Disable> Withered Vines of Desolation </> na área de combate. Durante este tempo, os jogadores ganham a habilidade temporária <Disable> Controle de Cogumelos </>. Usar <Disable> Controle de Cogumelos </> nas <Disable> Vinhas Murchadas da Desolação </> pode purificá-los. Se um número específico de <Disable> Withered Vines of Desolation </> for processado durante a mecânica, Sylvia entrará em estado de Fraqueza; caso contrário, ela usará <Disable> All Things Wither </> para matar todos. Se uma <Disable> Withered Vine of Desolation </> não for purificada dentro de 15 segundos após o surgimento, ela se transformará em uma área poluída que dura até o final da batalha.",
  [1046805399771648] = "Sylvia invoca <Disable> Cogumelos Estéreis </> e polui a área de caminhada, com uma área segura aparecendo aleatoriamente aos pés de Sylvia. Entrar na área poluída concede um acúmulo de efeito <Disable> Murchar </> a cada intervalo, durante o qual o HP diminuirá continuamente com base na Saúde máxima.",
  [933280287296768] = "Gere 1 vídeo usando a Escola de Arte",
  [1046805399771392] = "Sylvia tem como alvo todos os jogadores e adiciona um efeito de maldição <Disable> Blooming Mushroom </>. Afastar-se de Sylvia para quebrar a corda pode eliminar o efeito da maldição; caso contrário, um <Disable> Blooming Mushroom </> será gerado no local atual, liberando um ataque de área que diminui a distância. Sylvia irá gerar áreas de escudo com diferentes efeitos de proteção com base no número de <Disable> Blooming Mushrooms </> que aparecem, então lançará a habilidade <Disable> Descent of Vitality </>.",
  [1046805399771136] = "Sylvia gira 4 vezes e causa dano a alvos em um ângulo de 90° e num raio de 27 metros de sua orientação atual. Cada vez que ela gira, ela escolhe aleatoriamente 2 jogadores, adicionando um efeito <Disable> Tempo de Colheita </>. Quando o efeito terminar, com base em sua orientação atual, eles causarão dano massivo proporcional à sua Vida máxima a <Disable> alvos aliados </> dentro de um ângulo de 90° e raio de 27 metros.",
  [1046805399770880] = "Sylvia invoca 6 <Disable> Vines of Abundance </> , que atacarão continuamente o jogador com menor HP na área de combate. Posteriormente, Sylvia invoca uma área externa poluída e lança <Disable> Bounty Blessing </> para empurrar os jogadores de volta para a área poluída.",
  [1046805399770624] = "Sylvia convoca 6 <Disable> Guerreiros Cogumelos </>. Após um período de tempo, os Mushroom Warriors se transformarão em áreas poluídas. Entrar nessas áreas concede um acúmulo de efeito <Disable> Wither </> a cada intervalo, durante o qual o HP diminuirá continuamente com base na Saúde máxima.",
  [880024035002624] = "Klein pode coletar trinta balas da empresa todos os dias e depois ir para o campo de tiro subterrâneo na Rua Zoutland 3 para praticar tiro, onde há um campo exclusivo para Vigias Noturnos. Além disso, Klein tem que praticar combate por pelo menos duas horas todas as tardes, exceto nos dias de folga. \n\n \"O Instrutor Gawain é um instrutor de combate profissional e rigoroso; aprendi muito...\" Klein disse, com falta de ar depois de ser treinado a ponto de vomitar novamente. Mas, para melhorar suas habilidades de combate e sobrevivência, ele pratica sempre com a mesma diligência de um estudante que se prepara para o vestibular.",
  [1046805399770368] = "Sylvia convoca plantas poluídas; o Fungal Rot deixa uma área poluída no chão que dura 120 segundos, e o Withered Vine se fixa no jogador com maior ameaça para atacar.",
  [1046805399770112] = "Sylvia invoca o poder do Livro Dourado para formar meteoros que bombardeiam o solo.",
  [1046805399769856] = "Sylvia libera ventos alísios em grande escala, repelindo ou puxando jogadores para dentro do campo e causando dano.",
  [1046805399769600] = "Sylvia invoca a vontade da desolação da Árvore Dourada, causando danos massivos aos inimigos em uma área circular ou retangular.",
  [937060932260864] = "Classificação PVP",
  [1046805399769344] = "Sylvia invoca ventos alísios para soprar por toda a terra, causando dano moderado aos inimigos dentro da área dos ventos alísios.",
  [1046805399769088] = "A Tartaruga Gigante da Água do Infortúnio invoca 1 <Disable> área de Veneno de Cogumelo </> no campo. Após um intervalo, a Tartaruga Gigante irá plantar <Disable> Marcas de Infortúnio </> em 1 jogador aleatório; depois de um certo tempo, <Disable> Misfortune Water </> aparecerá aos pés do jogador. Após outro intervalo, a Tartaruga Gigante irá plantar marcas <Disable> Rose Castle </> em 1 jogador aleatório; depois de um certo tempo, <Disable> Rose Castle </> aparecerá aos pés do jogador. A área Mushroom Poison causará dano a <Disable> campo inteiro </> em intervalos. A área Misfortune Water irá gerar um <Disable> Pelican ou Bubble Puffer </> em intervalos para atacar os jogadores.",
  [1046805399768832] = "A Tartaruga Gigante da Água do Infortúnio seleciona o <Disable> alvo mais distante </> e, após um breve ataque, corre em direção ao alvo, causando <Disable> dano massivo a todo o campo </> após a conclusão. Porém, se <Disable> atingir um Rose Castle </> , ele ficará <Disable> Atordoado </> , interrompendo a Investida.",
  [1046805399768576] = "A Tartaruga Gigante da Água do Infortúnio invoca 3 <Disable> áreas de Veneno de Cogumelo </> no campo. Após um intervalo, a Tartaruga Gigante irá plantar <Disable> Marcas de Infortúnio </> em 3 jogadores aleatórios; depois de um certo tempo, <Disable> Misfortune Water </> aparecerá aos pés dos jogadores. Após outro intervalo, a Tartaruga Gigante irá plantar marcas <Disable> Rose Castle </> em 3 jogadores aleatórios; depois de um certo tempo, <Disable> Rose Castle </> aparecerá aos pés dos jogadores. As áreas de Veneno de Cogumelo causarão danos a <Disable> campo inteiro </> em intervalos. As áreas Misfortune Water irão gerar um <Disable> Pelican ou Bubble Puffer </> em intervalos para atacar os jogadores.",
  [1046805399768320] = "A Tartaruga Gigante da Água do Infortúnio lança sua carapaça e começa a atacar, <Disable> causando dano a todo o campo </> . Os jogadores podem pegar a concha e usá-la para bloquear o Ataque da Tartaruga Gigante.",
  [1046805399768064] = "A Tartaruga Gigante da Água do Infortúnio invocará <Disable> múltiplas ondas de Ondas do Mar </> em Sequência ; as ondas causam danos massivos se atingirem os jogadores.",
  [1046805399767808] = "A Tartaruga Gigante da Água do Infortúnio liberará uma habilidade de dano em área de 3 estágios. Após a 3ª etapa, 6 projéteis <Disable> Water Bullet </> aparecerão, atacando cada jogador. No início da habilidade, a Tartaruga Gigante invocará um <Disable> Cogumelo Venenoso de crescimento contínuo </> na sua frente. Quando o cogumelo atingir um determinado tamanho, ele <Disable> se autodestruirá </> .",
  [1033543882907904] = "Vínculo secreto de Frye",
  [1271036247298304] = "Mundo Extraordinário estreia em 26 de dezembro de 2026",
  [1271036247183616] = "Por favor clique para inserir texto",
  [409362728231936] = "Risos e Chamada ao Cortina do Vazio",
  [409362728248320] = "Amor e ódio",
  [1046805399766784] = "A Viscondessa divide o campo em 4 áreas, cada uma com 3 espelhos de cores diferentes. A cada período de tempo, 3 áreas aleatórias serão cobertas pela corrupção. Os jogadores precisam encontrar o <Disable> espelho correto </> para viajar por espiritualidade e chegar a uma área segura. Entrar no espelho errado resultará em corrupção espiritual e perda contínua de HP.",
  [1046805399766528] = "Após carregar por um período de tempo, a Viscondessa causará danos inevitáveis ​​a todo o campo. Os jogadores podem reunir o poder da Pulseira de Quatro Folhas quebrada para bloquear o Veredicto de Morte da Viscondessa.",
  [396306027644672] = "Família",
  [1046805399766272] = "Viscondessa ativa <Disable> Dark Scene </> , e todos entram na escuridão, o que causa dano contínuo aos jogadores. A Viscondessa lançará simultaneamente um Corte de amplo alcance nos jogadores que possuem uma Marca de Lealdade e limpará uma camada da Marca de Lealdade. Se o número total de barras da Viscondessa <Disable> exceder 3 vezes </> e todas as Marcas de Lealdade não tiverem sido apagadas, a paciência da Viscondessa desaparecerá e ela desferirá cortes indiscriminados em todos. Na escuridão, <Disable> a orientação do Pequeno Visconde </> aparecerá; siga as orientações para encontrar o Pequeno Visconde para dissipar a escuridão.",
  [1068726376488193] = "Sistema de Comando da Liga de Guildas Modificar Marca de Texto Interface Título de Rótulo Personalizado",
  [1046805399765248] = "Ancestor Armor invoca vários espíritos poluídos no campo. Uma vez que um espírito é atacado e resgatado, ele liberará <Disable> 1 característica misteriosa </> . Os jogadores que adquirirem as características misteriosas <Disable> se transformarão em Cavalaria </> durante a fase de duelo subsequente.",
  [1046805399764480] = "Ancestor Armor invoca vários espíritos esperando para serem revividos no campo. Os espíritos podem ser resgatados pela Cura; se o resgate falhar, o cavaleiro perderá o controle e ficará furioso!",
  [1011690284011520] = "Estilo Visual",
  [1011690283995136] = "Modo de saída",
  [1046805399764224] = "A Armadura Ancestral libera <Disable> corrupção corrosiva </> ao redor do campo enquanto convoca continuamente Alabardeiros do lado de fora para atacar o campo interno. A área poluída causa danos massivos aos jogadores. Os jogadores que adquiriram características misteriosas serão <Disable> transformados em Cavalaria imune a danos </> neste momento. Participar na matança de Halberdiers concede <Disable> Prova de Glória </> , que pode ser atualizada até o nível três. Após um período de tempo, Ancestor Armor inicia um duelo contra jogadores que possuem Proof of Glory. Se o duelo falhar, todos os jogadores serão punidos e a Armadura Ancestral ganhará Redução de Dano; se tiver sucesso, os jogadores ganham um aumento de dano.",
  [127888556820224] = "Depois de ingressar no culto, você pode obter automaticamente esta habilidade do Artefato Selado. Obtenha a habilidade especial [Charm], que pode ser liberada em outro Beyonders para iniciar um convite de charme.",
  [950391973873408] = "Ataque +516, Aprimoramento de Habilidade +108",
  [1240389777370368] = "O progresso da caça desta semana atingiu o limite de aquisição e não pode ser resgatado.",
  [1240389777419520] = "Código copiado com sucesso!",
  [1046805399763456] = "Ancestor Armor tem como alvo até 2 jogadores simultaneamente, então <Disable> lança um Leaping Slash nesses 2 jogadores em sucessão </> . O dano é extremamente alto e requer <Disable> várias pessoas para compartilhar </> , mas os jogadores atingidos pelo golpe não conseguem resistir a um segundo golpe no curto prazo.",
  [1046805399761920] = "O Cão de Caça mira continuamente em 1 jogador e então salta no ar para lançar um ataque de Salto de pressão naquele jogador. O dano do <Disable> Leap é extremamente alto e instantaneamente fatal </> , mas pode ser <Disable> compartilhado e mitigado por vários jogadores </> .",
  [1068726376209666] = "Magia",
  [1240389776715008] = "O nome do clube %s foi alterado para %s pelo presidente <HyperLink stylename=\"Chat_Name\" u=\"role=%s\"> [ %s ] </> .",
  [1240389776583936] = "A vontade de Roselle foi corroída pela Lua Vermelha; ele perdeu completamente o controle!",
  [1200668576584960] = "Faça Tingen ótimo",
  [1200668576617728] = "Príncipe do Abismo",
  [1200668845033216] = "Uma estrela em ascensão na ferrovia, sempre pronta para trazer resultados mais brilhantes. Participe do Railway Tycoon e ganhe do 11º ao 50º lugar no ranking semanal.",
  [224507604254976] = "Enum (valor não vazio do quadro-negro)",
  [1240389776977152] = "Não foi possível colocar este item.",
  [1240389776846080] = "Batalha encontrada; saiu automaticamente do modo foto.",
  [224507604271360] = "LuaList (IdGroup (todos os monstros))",
  [1046805399756800] = "O usuário do Astrolábio puxa todos à força em sua direção e invoca meteoritos; <Disable> cada jogador </> atrairá um, que causa dano de explosão ao pousar.",
  [272818201760256] = "Companheiro do Mundo Espiritual IV",
  [360778595065600] = "Eu me lembro agora.",
  [128163434727936] = "Padre",
  [804913646970368] = "A sala de jantar pode acomodar trezentos convidados ao mesmo tempo, e o chef principal já preparou para banquetes reais.",
  [580887615914752] = "Alcance um dano total ( %d ) ou cura ( %d ) de 20 milhões no campo de batalha Momento do Destino.",
  [822510396832256] = "Continue lendo",
  [1046805399752448] = "Sasrir se retira do campo de batalha e manipula a destrutiva água do Mar do Caos para convergir. <Disable> Após 30 segundos, afetará o campo de batalha, destruindo todos os seres vivos. </>",
  [1046805399752192] = "Sasrir invoca 2 Fantasmas de Sacrifício que se aproximam dele continuamente. <Disable> Cada Sacrifice Phantom que tocar Sasrir causará alto dano em todo o campo e aplicará 1 pilha de Sacrifice Burn Dano contínuo que dura 30 segundos a todos os jogadores. </>",
  [1046805399751936] = "Sasrir invoca vários avatares para transportar a Energia do Caos preta e branca para seu corpo principal. <Disable> Toda Energia do Caos que tocar Sasrir adicionará 1 pilha de fortalecimento a ela. </> Após um período de tempo, Sasrir libera Blasphemer's Death, causando dano contínuo em todo o campo. Cada pilha de aprimoramento de Energia do Caos aumenta esse dano em 20%.",
  [1187611070699520] = "Pegar texto",
  [1046805399751424] = "Sasrir canaliza a água do Mar do Caos, gerando 3 rios negros no campo. <Disable> Os rios entrarão em erupção após um intervalo, derrubando todos os jogadores acima deles </> e causando dano moderado.",
  [1046805399751168] = "Na segunda fase, quando a saúde de Milgongen cair para <Disable> 55%, 35%, 15% </> , ele liberará a habilidade Proteção de Quatro Símbolos. O dano em área circular aparecerá aleatoriamente no campo e todas as quatro estátuas ativarão o estado do laser simultaneamente. Duas estátuas <Disable> perderão sua proteção de invencibilidade </> . Os jogadores precisam destruir as estátuas que perderam a invencibilidade dentro de um determinado tempo. Se for bem sucedido, Milgongen entrará no estado Armor Broken.",
  [1046805399750912] = "Quando a saúde de Milgongen está abaixo de 75%, é <Disable> Fase 2 </> . Na segunda fase, Milgongen ganhará um certo efeito permanente de redução de danos. No entanto, quando Milgongen estiver <Disable> Armor Broken </> , o efeito de redução de dano será removido e a duração do estado Armor Broken de Milgongen será mais longa. Na segunda fase, 2 estátuas entram no estado de laser e 1 estátua entra no estado de campo mágico.",
  [1121504007818752] = "De acordo com cidadãos preocupados, estudantes da Universidade Hoy têm feito recentemente coisas estranhas no cemitério.",
  [1046805399750400] = "Quando as estátuas ativam o estado <Disable> Spell Field </> , elas irão gerar um campo mágico ao seu redor. Os jogadores dentro do campo mágico sofrerão continuamente dano de área.",
  [1046805399750144] = "Quando as estátuas ativarem o <Disable> estado Laser </> , elas liberarão um <Disable> Raio Laser </> fortalecido em direção a Milgongen. Quando o raio laser atinge Milgongen, ele adicionará periodicamente um <Disable> efeito de fortalecimento </> a Milgongen. O laser pode ser interceptado pelos jogadores.",
  [1046805399749888] = "Existem seis <Disable> Estátuas de Guardiões </> no campo de batalha. As estátuas são inicialmente invencíveis. Durante a segunda fase, quando Milgongen libera a Proteção dos Quatro Símbolos, as estátuas perderão sua invencibilidade em Sequência . Para cada estátua que existe, Milgongen ganha um certo efeito de <Disable> bloqueio de saúde </>. Todas as estátuas devem ser destruídas antes que Milgongen possa ser morto.",
  [611604416711168] = "Poção do Cavaleiro da Punição",
  [695033619596800] = "Os produtos são cuidadosamente empilhados no vagão e os trilhos levam a uma estação desconhecida e movimentada.",
  [1121502665648128] = "Conexão Telepática",
  [527835374644992] = "Onde desenhar para Marionetes",
  [418367932478464] = "Aumenta a Defesa em 140.",
  [70575976352512] = "Recomendação de história",
  [1152429919887873] = "Aprovando público",
  [1046805399748096] = "Ouroboros atribuirá simultaneamente um efeito de destino aleatório a todos os jogadores, Medici e Alista, que são <Disable> Sucesso </> e <Disable> Falha </> . Se os jogadores atacarem um inimigo com o mesmo destino que eles, eles sofrerão enorme <Disable> dano refletido </> .",
  [1046805399747840] = "Os destinos de Medici e Alista estão ligados. Se os jogadores não conseguirem matá-los ao mesmo tempo, o poder de Retrace de Ouroboros fará com que eles <Disable> ressuscitem </> de novo e de novo.",
  [1046805399747584] = "Texto geral da descrição da jogabilidade <Disable> texto chave </> texto geral da descrição da jogabilidade.",
  [1046805399747328] = "O Dark Demonic Wolf faz um desejo para si mesmo, adicionando um efeito <Disable> Dark Light </> a todos os jogadores. Dark Light causará danos contínuos aos jogadores e gradualmente removerá sua luz.",
  [752090918263040] = "O Dancing King Baboon Brother era originalmente apenas um babuíno comum à beira do lago. A única coisa que importava era se conseguiria encontrar pão hoje. Até que o poder da Árvore da Abundância permeasse sua carne e sangue, de repente ela teve uma epifania – aqueles movimentos estranhos que os humanos faziam, balançando os braços e chutando as pernas na grande árvore, eram na verdade chamados de dança! Ele batia os dedos dos pés no ritmo e logo se viciou; o que era comer comparado a dançar, o que era migalhas comparado ao ritmo? Tornou-se o rei da dança do Lago Dourado do Outono, liderando a tropa de babuínos para dançar de manhã à noite, tentando convidar todos os viajantes que passavam para participar.\n",
  [1046805399747072] = "O Dark Demonic Wolf puxa os corpo espiritual fios de todos os jogadores e os atrai para o seu lado. Os corpo espiritual threads de jogadores conectados em pares são interrompidos, causando dano continuamente uns aos outros.",
  [1046805399746816] = "O Lobo Demoníaco Negro convoca 2 <Disable> Parentes do Lobo Demoníaco </>. Após o surgimento do <Disable> Demon Wolf Kin </>, eles entrarão em um estado de invisibilidade, continuarão a se mover ao longo da borda do campo e liberarão periodicamente danos em todo o campo que se tornam cada vez maiores. Enquanto os <Disable> Demon Wolf Kin </> existirem, eles protegerão o <Disable> Dark Demonic Wolf </>, mantendo-o em um estado invencível.",
  [224508946445568] = "{\n \"Poça (semelhante ao material da poça de Tingen, não à superfície real da água)\": \"0\", \n \"Grama\": \"1\", \n \"Pedra\": \"2\", \n \"Sujeira\": \"3\", \n \"Madeira\": \"4\", \n \"Cobertor\": \"5\", \n \"Tecido\": \"6\", \n \"Vidro\": \"7\", \n \"Gelo\": \"8\", \n \"Pântano\": \"9\", \n \"Metal Sólido\": \"10\", \n \"Areia\": \"11\", \n \"Neve\": \"12\", \n \"Placa de Aço\": \"13\", \n \"Poça de Azulejo\": \"14\", \n \"Superfície da Água\": \"15\", \n \"Tábua de Madeira\": \"16\" \n}",
  [1068726108357376] = "Novo conteúdo desbloqueado",
  [571884827588352] = "Sendo requisitado por %s ...",
  [571884827580160] = "Dano aumentado: %s acúmulos",
  [1068726108046080] = "A partida %s começará em %s %s",
  [1068726108103424] = "Mural de Contribuições do Clube",
  [611329270352128] = "Multar",
  [628922798580224] = "Ver detalhes",
  [1068726107857664] = "Arraste o marcador para a cena para marcar",
  [1068726107898624] = "Místico Espiritualidade",
  [1068726107972352] = "Poção de fermentação",
  [357135925908480] = "Cor sarda",
  [1068726107636480] = "Resultado da Síntese",
  [224507872701696] = "Tempo de estatísticas",
  [224507872683264] = "ID do estado",
  [224507872677120] = "Pilhas de comparação",
  [1046805399744512] = "Depois de entrar em combate, Gulu aumentará continuamente seu <Disable> Valor de Fome </> ao longo do tempo, até um máximo de 100. Quando o Valor de Fome atingir <Disable> 100 </> , Gulu lançará <Disable> Hunger Devour </> , puxando 3 jogadores aleatórios para sua frente para devorá-los.",
  [224507872707840] = "Orientação B",
  [224508141127936] = "0: Masculino \n 1: Feminino \n 2: Sem gênero",
  [224508141115648] = "(Unidade °) O alvo à esquerda é negativo, à direita é positivo; preencha um valor maior que o valor do ângulo inicial, intervalo [-180, 180].",
  [1046805399744256] = "<Disable> Filthy Cubs </> aparecerão continuamente no campo, vagando aleatoriamente quando aparecerem. Depois de esvaziar a barra de saúde de um filhote, os jogadores podem usar a habilidade <Disable> Empurrar </> para empurrar o filhote para frente uma certa distância. Se um filhote for empurrado para baixo de Gulu, ele será <Disable> devorado </> por Gulu, e cada devoração bem-sucedida reduzirá o Valor de Fome de Gulu.",
  [1033542272289024] = "Saudação",
  [664107976064512] = "<M_Default> Prezado Beyonder : </> \n <M_Default> Parabéns por se classificar entre os 100 melhores do país para sua profissão no modo Companion. Você recebeu um título honorário. Você pode ir para </> <HyperLink stylename=\"M_Link\" u=\"jump=1250011\"> [Menu - Character - Title Interface] </> <M_Default> para usá-lo. </>",
  [664107975974400] = "<M_Default> Prezado Beyonder: </> \n <M_Default> O dinheiro do presente que você enviou não foi totalmente reivindicado. A parte não reclamada foi devolvida a você de acordo com as regras do dinheiro para presentes. Por favor, colete-o dos anexos a tempo. </>",
  [664107976007168] = "<M_Default> Caro Beyonder : </> \n <M_Default> Um Contrato do Despertar chegou – um pedido vinculativo do Senhor dos Mistérios. </> \nClique em <HyperLink stylename=\"M_Link\" u=\"web=%s\"> Confirmar vinculação </> para concluir a assinatura do contrato. \n Se isso não foi feito por você, ignore este e-mail. \nObrigado por testemunhar esta jornada. Que seu espiritualidade guie seu caminho adiante.",
  [1046805399744000] = "Gulu libera continuamente <Disable> névoa venenosa </> , causando múltiplas rodadas de dano em todo o campo, enquanto seu próprio Valor de Fome aumenta em uma quantidade fixa.",
  [1046805399743744] = "Gulu salta alto e bate no chão, causando dano de área no local de pouso e gerando uma onda de choque terrestre <Disable> em expansão contínua </> , causando dano aos inimigos atingidos.",
  [1046805399743488] = "Gulu trava na direção da corrente <Disable> ameaça alvo </> e borrifa ácido gástrico continuamente, causando grande dano em área.",
  [664106365445632] = "Recompensas do título de classificação da cidade da Batalha pelo Trono de Deus",
  [127888019949312] = "Espelho folheado a prata",
  [664106365396480] = "E-mail de aviso de pedido do baile noturno de primavera",
  [1046805399743232] = "Gulu bate continuamente com suas mãos gigantes no chão, causando várias rodadas de <Disable> dano aleatório de área circular ou em forma de anel </> ao seu redor.",
  [1108720842968064] = "Sétimo Assento",
  [1046805399742720] = "O Palhaço Feliz sonha com <Disable> uma roda gigante, que atribuirá naipes aleatoriamente aos jogadores </> . Após um período de tempo, os jogadores que não estiverem na área correspondente ao seu naipe na roda serão punidos pelo Palhaço.",
  [1046805399742464] = "O Palhaço Triste sonha com <Disable> uma grande bomba, que atingirá aleatoriamente um jogador </> . Após um período de tempo, ele explode no local daquele jogador, causando dano massivo, mas esse dano pode ser compartilhado por companheiros de equipe dentro do alcance.",
  [646519011179264] = "1º de setembro de 1319",
  [1046805399742208] = "Faixas mágicas retangulares que seguem os jogadores aparecem sob <Disable> os pés de todos os jogadores </> . Após um breve intervalo, eles explodem com energia arcana, causando dano a todos os jogadores dentro do alcance.",
  [1046805399741952] = "Riel Bieber <Disable> invoca a Cidade da Noite de sua memória para prender os jogadores e transformá-los em fantoches </> , então começa a liberar a habilidade <Disable> Escudo de Perda de Controle </> .",
  [998357631764736] = "Estrela das Estrelas · Sigilo",
  [611604416712192] = "Poção da Mão da Ordem",
  [695033619597056] = "Planeje os tijolos, mesas, cadeiras e seu ritmo de vida único aqui.",
  [527766923601152] = "Expositor - Convite",
  [527835374645248] = "Como adquirir um Marionete",
  [418367932478720] = "Aumenta a resistência crítica em 160.",
  [514641771946496] = "Despejar o instantâneo da memória Lua; digite outFile.",
  [272818201760512] = "Companheiro do Mundo Espiritual V",
