  [664106365405696] = "Uma carta de Azik Eggers",
  [527767192156160] = "<Assistant_Title1> 【Corrente de Platina】 </> \n <Assistant_Title2> Descrição: </> Recompensa de Progresso do Livro de Bronze\n <Assistant_Title2> Uso: </> Após o uso, obtenha a Corrente de Platina; você pode clicar em <Assistant_System> Appearance-Change Outfit </> para visualizá-lo e usá-lo.\n <Assistant_Title2> Aquisição: </> Obtido via <Assistant_System> Masmorra </>",
