  [730076526180352] = "Ainda não há presentes",
  [862028122140673] = "Um papel com \"Reino de Loen, Departamento de Polícia do Condado de Awwa, Departamento de Operações Especiais, Sétima Unidade\" escrito nele.",
  [519177257430017] = "Quer vir dar uma olhada?",
  [765265461645312] = "<Color_Warrior> Corpo a corpo Defesa </>",
  [316729142078464] = "Selena Alienada - Corpo espiritual Decoração",
