  [804913646956800] = "Ah... haha, contanto que você esteja feliz.",
  [527767192163072] = "<Assistant_Title1> Invincible Brawl King </> \n <Assistant_Title2> Categoria de conquista: </> Lazer-Diversão\n <Assistant_Title2> Condição de desbloqueio: </> Classifique-se entre os três primeiros como jogador por um total de três temporadas",
