  [527767192116992] = "<Assistant_Title1> Favor do Bispo de Guerra </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <War Bishop>",
