  [224646117181184] = "{\n \"Cancelar automaticamente o destaque após clicar\": \"0\", \n \"Não cancelar automaticamente o destaque após clicar\": \"1\", \n}",
  [611398258412800] = "Através dos Quatro Mares",
  [664107975983104] = "Lamentamos que você tenha perdido na quarta rodada da fase de grupos. A recompensa foi enviada automaticamente para sua caixa de correio.",
