  [527767192000768] = "<Assistant_Title1> 【Aglomerado de Flores de Réquiem】 </> \n <Assistant_Title2> Descrição: </> Acessório de compra direta na loja\n <Assistant_Title2> Uso: </> Compre na loja para obter o Conjunto de Flores de Réquiem. Você pode clicar em <Assistant_System> Aparência - Mudar roupa </> para visualizá-lo e usá-lo.\n <Assistant_Title2> Aquisição: </> Obtido via <Assistant_System> Loja </>",
