  [527767191997696] = "<Assistant_Title1> 【Green Field Journey】 </> \n <Assistant_Title2> Descrição: </> Roupa de compra direta na loja\n <Assistant_Title2> Uso: </> Compre na loja para obter a roupa Green Field Journey. Você pode clicar em <Assistant_System> Aparência - Mudar roupa </> para visualizá-lo e usá-lo.\n <Assistant_Title2> Aquisição: </> Obtido via <Assistant_System> Loja </>",
  [26389621247744] = "Condado Castanho-Dourado",
  [905998655034368] = "Modo Sala 1v1",
  [611606832684800] = "Porcelana branca, bonita e simples.",
  [611606832684544] = "O nome é vinho, mas na verdade não contém álcool. É misturado com suco de gengibre e limão para criar um sabor semelhante ao da cerveja. É uma bebida que mulheres e crianças podem aceitar, mas Melissa não gosta desse sabor.",
  [611606832684288] = "Sobremesa exclusiva da Sra. Slin, acessível e deliciosa, apreciada por adultos e crianças.",
  [611606832683776] = "Poção dada a Klein por Dunn, o frasco é pequeno e requintado, e o líquido dentro flui lentamente.",
  [611606832683520] = "O café cuidadosamente elaborado da Klein.",
  [611606832683264] = "Pó estranho dado pelo Velho Neil.",
  [611606832683008] = "Uma pequena caixa pesada e resistente contendo alguns materiais estranhos: latas com padrões prateados, tubos de ensaio cheios de pó preto, frascos escuros e muito mais. Os materiais estão organizados de maneira organizada e a caixa tem uma etiqueta que diz “Materiais da Poção Vidente”.",
  [611606832682752] = "4 semanas de salário adiantado - graças à generosidade e consideração do capitão.",
  [611606832682496] = "Balas para pistola, suprimentos obtidos ao ingressar no esquadrão Vigias Noturnos.",
  [611606832682240] = "Um diário de um soldado Loen, registrando os pedaços da guerra. Há também muitos esboços de soldados que, embora toscos, têm postura vívida, mostrando uma base profunda no desenho.",
  [611606832681984] = "Carteira gasta com alguns trocos. Há também a foto de uma jovem na camada intermediária, que está desbotada por ser esfregada.",
  [827108427302400] = "Limite de compra",
  [611606832681472] = "Jaqueta de couro velha, lampião de querosene e um pouco de pão e carne de veado... Um presente generoso do velho caçador Jonah, esperando que isso ajude Braden e seus camaradas.",
  [611606832681216] = "Uma nota enfiada nas páginas de \"Subconsciente e sua musicalidade\".",
  [611606832680960] = "Uma foto limpa de poeira, tirada no trem quando Pete trouxe Enid para Tingen.",
  [611606832680704] = "O boneco passarinho deve ser um brinquedo que Enid gosta muito.",
  [611606832680192] = "Um livro registrando doenças e misticismo, remédios populares.",
  [611606832679936] = "Medalha toscamente desenhada, o desenho é incrível.",
