  [527835374641920] = "Por que a favorabilidade do NPC não está aumentando?",
  [519177257356545] = "Pegue o Bolo, <P_Yellow> Arraste o botão Habilidade </> para jogá-lo",
  [519177257360641] = "As vagas estão ocupadas, aguarde a próxima!",
  [519177257393409] = "(É tão rude, não entendo porque papai gosta de vir para este lugar...)",
