  [360778595248896] = "Conhecimento infinito, originado do vasto céu estrelado.",
  [360778595227392] = "... <P_Heart> (Onde é isso? O que eu quero fazer? Eu também quero saber...) </>",
  [360778595236608] = "Olá, senhorita Rozanne.",
  [519109343506688] = "Alberto",
  [519109343543552] = "Voz no nevoeiro",
