  [527767460389377] = "Caminho Avaliação",
  [527767460388866] = "Correio do Clube",
  [1103979467511296] = "O trovão destrói a torre e a verdade fica exposta nas ruínas. Abrace esta destruição; é o início da reconstrução.",
  [527767460388097] = "Herança de memória",
