  [527767460384002] = "Briga",
  [527767192190976] = "<Assistant_Title1> [Julgamento do Mapa Estelar] </> \n <Assistant_Title2> Descrição: </> Moda de recompensa de nível de culto \n <Assistant_Title2> Uso: </> Após o uso, ganhe o conjunto Julgamento do Mapa Estelar, que pode ser visualizado e usado clicando em <Assistant_System> Aparência - Vestir </> . \n <Assistant_Title2> Aquisição: </> desbloqueado por nível de culto",
  [611398258534912] = "Notas Policiais de Alto Nível (IV)",
  [57451898486784] = "Vigilância Noturna de Sucesso!",
  [611398258395648] = "Social: recusar",
  [611398258354688] = "Cobertor de pele de raposa branca do Ártico",
