  [57451898482688] = "Difícil: Tartaruga!",
  [57451898478592] = "Difícil · Proteção à prole",
  [57451898482176] = "Babuíno!",
  [527767192189952] = "<Assistant_Title1> [Naturalmente Suave] </> \n <Assistant_Title2> Descrição: </> Penteado de Venda Direta no Shopping \n <Assistant_Title2> Uso: </> Após comprar no Shopping, ganhe o penteado Naturalmente Suave, que pode ser visualizado e usado clicando em <Assistant_System> Aparência - Vestir </> . \n <Assistant_Title2> Aquisição: </> Obtida através do <Assistant_System> Shopping </>",
  [527767192189440] = "<Assistant_Title1> [In the Evening Breeze] </> \n <Assistant_Title2> Descrição: </> Mall Direct-Sale Fashion \n <Assistant_Title2> Uso: </> Após comprar no Mall, ganhe o conjunto In the Evening Breeze, que pode ser visualizado e usado clicando em <Assistant_System> Aparência - Vestir </> . \n <Assistant_Title2> Aquisição: </> Obtida através do <Assistant_System> Shopping </>",
