  [519041160630016] = "Legumes frescos!",
  [519041160629760] = "Todos estes são vegetais locais de Tingen, vegetais sazonais.",
  [519041160628480] = "Último pedaço de legumes, vendendo barato!",
  [519041160628224] = "Venha comprar, preços de atacado.",
  [519041160625920] = "Acho que combinaria bem com o chá preto Sibe.",
  [1200738906675712] = "Título do ranking nacional da Batalha pelo Trono de Deus",
