  [514572247116800] = "Clube do Tarô",
  [1169950433787136] = "Siga Rebeca",
  [804913647059712] = "Ah, Sra. Dalov. Você sabe, todos os alunos desta escola devem passar por um exame rigoroso para solicitar admissão.",
  [804913647092480] = "Ei, Gabriel, não é legal dizer isso. Talvez Lino tenha sua própria música?",
  [804913646936832] = "Minha querida, eu também deveria ter adivinhado. Estávamos ambos muito ansiosos para preparar uma surpresa um para o outro!",
  [804913646961408] = "Olá.",
  [804913647026944] = "<P_Heart> (Atordoado por um momento) </> Spinel? Não é um rubi?",
  [822506101738496] = "Espectador suspeito",
  [822506101550080] = "Edmundo",
  [281888635750912] = "Guia final",
  [360778595117312] = "Terrível, ele está ficando um pouco louco, preciso controlá-lo primeiro",
  [360778595109120] = "Espero que você possa pelo menos sentir felicidade no reencontro.",
  [360778595051776] = "Não, ele vai fugir!",
  [360778595043584] = "Por que o lago é tão estranho... Preciso sair daqui.",
  [360778595076352] = "Melissa: Ok...",
  [360778595240192] = "Finalmente acabou... Bom dia, Rozanne.",
  [360778595182848] = "E isso.",
  [360778595174656] = "Isso ocorre porque o poder da poção está transbordando e você não tem como controlá-la.",
  [360778595207424] = "Finalmente acabou... Bom dia, Rozanne.",
  [360778595375360] = "???: O que você sabe! Não demorará muito, em breve retomaremos a glória que nos pertence!",
  [360778595313920] = "Que coincidência, senhorzinho vendedor de jornais, nos reencontramos.",
  [360778595309824] = "Beyonder poderes são perigosos.",
  [360778595338496] = "Mas Neil, eu andei um pouco mais rápido.",
  [862018189943296] = "Partidas",
  [360778595444992] = "Audrey: Não a representante de Bonnie, mas a 'humanidade' que ela descartou para se tornar uma Bruxa.",
  [360778595436800] = "Quase lá. Contanto que eu possa dar esse passo...",
  [514572247113984] = "Exploração de mundo aberto",
  [141494476342784] = "Saúde",
  [382906803422720] = "Prata da Razão",
  [862024901287936] = "Alcance ela",
  [862024901197824] = "Tente sentar",
  [862024900886528] = "Pequena barraca de livros",
