  [224645311738112] = "Modo de link",
  [369505700153600] = "Reanimação automática nas proximidades",
  [369505700153088] = "Ressuscitar nas proximidades",
  [369438054419968] = "Jogadores da mesma família que participam de um masmorra podem receber bônus de atributos e contagens extras de ressurreição.",
  [369437785986816] = "A reanimação consumirá as tentativas de reanimação restantes.",
