  [193515657143808] = "A hora em que o enorme tiro soou foi uma noite tão clara quanto o dia",
  [950735034392578] = "Prioridade de Ataque",
  [193515657143296] = "A luz ofuscante que apareceu de repente no meio da noite fez as pessoas confundirem a hora com a manhã",
  [193515657143040] = "O local onde o Estripador foi encerrado fica fora da sede da polícia",
  [193515657142784] = "A garota atraiu intencionalmente o Estripador até a sede da polícia",
  [1240253948120065] = "<Highlight> Envie materiais da Relíquia Carmesim para o Mordomo da Caçada </> para avançar no <Highlight> Progresso da Caçada </> e desbloquear <Highlight> recompensas valiosas </> para cada estágio. Observação: <Highlight> Crimson Relics só são eficazes na Cidade de Dragon Hunting </> ; eles <Highlight> expirarão automaticamente e serão liberados </> ao sair.",
  [193515657142272] = "A estrada principal para a qual a garota fugiu em pânico",
  [193515657142016] = "A beira do rio onde o Estripador se preparava para subir ao palco",
  [193515657141760] = "O personagem que acabou com o Estripador é o capitão da polícia",
  [1219223103739904] = "Número acumulado de bebidas alcoólicas vendidas chega a 10 mil",
  [193515657141248] = "O vice-capitão que jurou matar o Estripador, mas não conseguiu",
  [193515657140992] = "A lenda do Estripador acabou; ele foi baleado e morto por alguém",
  [193515657140736] = "O capitão que foi emboscar o Estripador com uma arma",
  [193515657138432] = "O roteiro falante alterou o tempo; a resposta atual não é a correta",
  [193515657138176] = "O horário apresentado no palco é... noite",
  [193515657137920] = "O personagem que salvou a garota é o assistente do detetive",
  [1059999002410752] = "Entre no combate",
  [466743759738368] = "Peça única",
  [602604581171968] = "Desbloqueie obtendo o traje Light and Dark Twin",
  [193515657136896] = "O adivinho que descobriu todos os seus adereços foram roubados pelo assistente do detetive",
  [193515657136640] = "O detetive reclamando que seu assistente fugiu de repente na frente da adivinhação barraca",
  [193515657136384] = "A garota de vestido longo é quem brinca de fantasma no esconde-esconde",
  [193515657136128] = "O Estripador olhando fixamente para a garota das sombras",
