  [175991653664768] = "[Emoji3]",
  [140946331160320] = "Cada ataque básico de uma peça [Fog Forest Kin] concede <HighLight> 1 </> pilha(s) de [Moss Shadow Absorção], com cada pilha concedendo <HighLight> 2% </> de Roubo de Vida e <HighLight> 1% </> de Vida Máxima, acumulando até <HighLight> 6 </> vezes.",
  [140946331160064] = "Quando Anthea entrar em campo, convoque o Sr. Barney do mesmo nível de estrela de Anthea como uma convocação para se juntar à batalha.",
  [140946331158784] = "O dano causado por peças de [Criatura Sobrenatural] é aumentado em <HighLight> 50% </> ; depois de participar de <HighLight> 4 </> rodadas de combate de jogadores, ganhe <HighLight> 25% de </> Redução de Dano adicional.",
  [140946331158528] = "O dano causado por peças de [Criatura Sobrenatural] é aumentado em <HighLight> 30% </> ; depois de participar de <HighLight> 4 </> rodadas de combate de jogadores, ganhe <HighLight> 15% de </> Redução de Dano adicional.",
  [140946331158272] = "O dano causado por peças de [Criatura Sobrenatural] é aumentado em <HighLight> 20% </> ; depois de participar de <HighLight> 4 </> rodadas de combate de jogadores, ganhe <HighLight> 10% de </> Redução de Dano adicional.",
  [140946331158016] = "O dano causado por peças de [Criatura Sobrenatural] é aumentado em <HighLight> 10% </> ; depois de participar de <HighLight> 4 </> rodadas de combate de jogadores, ganhe <HighLight> 5% de </> Redução de Dano adicional.",
  [140946331157760] = "<HighLight> 8 </> segundos após o início da batalha, causa <HighLight> 700 </> de dano verdadeiro em toda a tela, todos os aliados ganham + <HighLight> 50% </> de Velocidade de Ataque.",
  [140946331157504] = "<HighLight> 8 </> segundos após o início da batalha, causa <HighLight> 500 </> de dano verdadeiro em toda a tela, todos os aliados ganham + <HighLight> 40% </> de Velocidade de Ataque.",
  [140946331157248] = "<HighLight> 8 </> segundos após o início da batalha, causa <HighLight> 350 </> de dano verdadeiro em toda a tela, todos os aliados ganham + <HighLight> 30% </> de Velocidade de Ataque.",
  [140946331156992] = "<HighLight> 8 </> segundos após o início da batalha, causa <HighLight> 200 </> de dano verdadeiro em toda a tela, todos os aliados ganham + <HighLight> 20% </> de Velocidade de Ataque.",
  [140946331156480] = "Invoque <HighLight> 2 </> estátuas de Deus; aliados dentro de <HighLight> 1 </> bloco da estátua ganham <HighLight> 30% </> de Vida máxima e <HighLight> 22% </> de Aumento de Dano; Peças de [Terra Abandonada dos Deuses] ganham um efeito adicional de <HighLight> 50% </>. O efeito é perdido imediatamente ao sair do intervalo durante a fase de preparação; após o início da batalha, o efeito persiste por <HighLight> 45 </> segundos após sair do alcance. Efeitos semelhantes não se acumulam.",
  [140946331156224] = "Invoque <HighLight> 2 </> estátuas de Deus; aliados dentro de <HighLight> 1 </> bloco da estátua ganham <HighLight> 18% </> de Vida máxima e <HighLight> 14% </> de Aumento de Dano; Peças de [Terra Abandonada dos Deuses] ganham um efeito adicional de <HighLight> 50% </>. O efeito é perdido imediatamente ao sair do intervalo durante a fase de preparação; após o início da batalha, o efeito persiste por <HighLight> 45 </> segundos após sair do alcance. Efeitos semelhantes não se acumulam.",
  [140946331155968] = "Convocar <HighLight> 1 </> estátua de Deus; aliados dentro de <HighLight> 1 </> bloco da estátua ganham <HighLight> 10% </> de Vida máxima e <HighLight> 8% </> de Aumento de Dano; Peças de [Terra Abandonada dos Deuses] ganham um efeito adicional de <HighLight> 50% </>. O efeito é perdido imediatamente ao sair do intervalo durante a fase de preparação; após o início da batalha, o efeito persiste por <HighLight> 45 </> segundos após sair do alcance. Efeitos semelhantes não se acumulam.",
  [140946331155712] = "Acumule Alabarda Devota, Capa Noturna do Morcego Sangrento e Olho do Dragão Espelhado.",
  [140946331155456] = "Acumule Alabarda Devota e Capa Noturna de Morcego Sangrento.",
  [470599029753600] = "Nightmare Impact inflige um efeito de Ferimento Grave por 3 segundos ao atingir um alvo em perseguição, com um efeito de Ferimento Grave de 66%.",
  [140946331154944] = "Ganhe <HighLight> 30% </> de Ataque e <HighLight> 10% </> de Redução de Dano por <HighLight> 4 </> segundos após liberar uma habilidade; recuperar <HighLight> 20 </> de mana ao matar habilidade.",
  [140946331154688] = "Ganhe <HighLight> 15% </> de Ataque e <HighLight> 5% </> de Redução de Dano por <HighLight> 4 </> segundos após liberar uma habilidade; recuperar <HighLight> 20 </> de mana ao matar habilidade.",
  [140946331154432] = "Para cada <HighLight> 1 </> peça inimiga que cai, peças de [Life Sect] ganham permanentemente <HighLight> 12 </> de Vida máxima.",
  [140946331154176] = "Para cada <HighLight> 1 </> peça inimiga que cai, peças de [Life Sect] ganham permanentemente <HighLight> 8 </> de Vida máxima.",
  [140946331153920] = "Para cada <HighLight> 1 </> peça inimiga que cai, peças de [Life Sect] ganham permanentemente <HighLight> 4 </> de Vida máxima.",
  [140946331153408] = "Recupere <HighLight> 2 </> Saúde no início da batalha de cada jogador; ganhe <HighLight> 50 </> pontos de sorte após vencer uma batalha de jogador.",
  [140946331153152] = "Recupere <HighLight> 2 </> Saúde no início de cada batalha entre jogadores.",
  [140946331152896] = "Abra missões de sorte. Complete-os para ganhar pontos de sorte; assim que os pontos atingirem o limite, você poderá optar por reivindicar recompensas.",
  [140946331152640] = "Convocar Vontade Carmesim, Forma <HighLight> 4 </>",
  [140946331152384] = "Invoque <HighLight> 3 </> estrelas Crimson Will.",
  [140946331152128] = "Invoque <HighLight> 2 </> estrelas Will Carmesim.",
  [140946331151872] = "Invoque <HighLight> 1 </> estrela Crimson Will.",
  [140946331151616] = "No início da batalha, reduza a Defesa de todos os inimigos em <HighLight> 30% </> por <HighLight> 30 </> segundos; a cada rodada, obtenha aleatoriamente <HighLight> 1 </> <HighLight> 1 </> - pedaço de estrela de peças inimigas mortas na batalha anterior.",
  [140946331151360] = "No início da batalha, reduza a Defesa de todos os inimigos em <HighLight> 15% </> por <HighLight> 15 </> segundos; a cada rodada, obtenha aleatoriamente <HighLight> 1 </> <HighLight> 1 </> - pedaço de estrela de peças inimigas mortas na batalha anterior.",
  [140946331151104] = "No início da batalha, reduza a Defesa de todos os inimigos em <HighLight> 10% </> por <HighLight> 10 </> segundos; a cada rodada, obtenha aleatoriamente <HighLight> 1 </> <HighLight> 1 </> - pedaço de estrela de peças inimigas mortas na batalha anterior.",
  [866762786605056] = "Diário",
  [140946331150592] = "[Evernight Goddess] executa alvos inimigos com Saúde abaixo de <HighLight> 18% </>.",
  [439944505987840] = "Na alta sociedade do Reino de Loen, a valorização da moda é um símbolo de status e educação. \n Cavalheiros e senhoras têm requisitos rígidos em relação ao vestuário – combinar trajes apropriados de acordo com a ocasião, status e estação do ano é a única maneira de ganhar respeito nos círculos sociais. \n Mostre sua estética por meio de desafios de apreciação e torne-se famoso nos círculos superiores.",
  [140946331150080] = "<HighLight> 25% </> Ataque, <HighLight> 20% </> Roubo de Vida adicional.",
  [140946331149824] = "<HighLight> 15% </> de ataque, <HighLight> 10% </> de roubo de vida adicional.",
  [140946331149568] = "Clube do Tarô atributos únicos aumentados para <HighLight> 220% </> de efeito.",
  [140946331149312] = "Clube do Tarô atributos únicos aumentados para <HighLight> 190% </> de efeito.",
